def _m37_normalized_operational_events(
    rows: Sequence[Sequence[Any]],
) -> list[dict[str, Any]]:
    """Rehash and normalize the exact event-287..290 bridge."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    result: list[dict[str, Any]] = []
    for raw in rows:
        if len(raw) != 10:
            raise MigrationRequired("M37 operational event row width differs")
        row = [raw[index] for index in range(10)]
        try:
            event_body = json.loads(str(row[9]))
        except (TypeError, ValueError) as exc:
            raise MigrationRequired("M37 operational event JSON differs") from exc
        inner = event_body.get("body") if isinstance(event_body, Mapping) else None
        receipt = inner.get("receipt") if isinstance(inner, Mapping) else None
        if (
            not isinstance(inner, Mapping)
            or not isinstance(receipt, Mapping)
            or row[1] != "stream:intent"
            or int(row[2]) != int(row[3])
            or row[4] != "intent.task_status_changed"
            or row[6] not in (None, "")
            or row[7] != "session:intent"
            or event_body.get("schema")
            != "ipfs_accelerate_py/agent-supervisor/intent-event@1"
            or event_body.get("event_type") != row[4]
            or event_body.get("subject_id") != row[5]
            or event_body.get("recorded_at") != row[8]
            or inner.get("task_cid") != row[5]
            or str(row[0])
            != content_identity(
                {
                    "stream_id": row[1],
                    "sequence": int(row[2]),
                    "global_sequence": int(row[3]),
                    "event_type": row[4],
                    "body": event_body,
                }
            )
        ):
            raise MigrationRequired("M37 operational event envelope differs")
        result.append(
            {
                "global_sequence": int(row[3]),
                "event_id": str(row[0]),
                "event_type": str(row[4]),
                "task_alias": str(inner.get("task_alias") or ""),
                "task_cid": str(inner.get("task_cid") or ""),
                "previous_status": str(inner.get("previous_status") or ""),
                "status": str(inner.get("status") or ""),
                "revision": int(inner.get("revision") or 0),
                "operation": str(receipt.get("operation") or ""),
                "attempt_id": str(receipt.get("attempt_id") or ""),
                "claim_id": str(receipt.get("claim_id") or ""),
                "lease_id": str(receipt.get("lease_id") or ""),
                "recorded_at": str(row[8]),
            }
        )
    return result


def _m38_lane_pid_evidence() -> dict[str, dict[str, Any]]:
    """Return the closed, credential-free stale lane PID evidence."""

    result: dict[str, dict[str, Any]] = {}
    for lane, evidence in _M38_LANE_PID_EVIDENCE.items():
        lane_number = int(lane.split("-", 1)[1])
        result[lane] = {
            "path": (
                f"{_M38_RUNTIME_ROOT}/state/lane-{lane_number}/"
                f"sawm_lane_{lane_number}_supervisor.pid"
            ),
            **dict(evidence),
            "mode": 0o664,
            "uid": 1000,
            "gid": 1000,
            "link_count": 1,
            "device": 66306,
            "owner_liveness": "dead",
            "liveness_probe": "kill_pid_0_process_lookup_error",
        }
    return result


def _m38_source_identities_pending() -> bool:
    runtime_identities = (
        _M38_RUNTIME_REPAIR_COMMIT,
        _M38_RUNTIME_REPAIR_TREE,
        *tuple(_M38_RUNTIME_REPAIR_BLOBS.values()),
    )
    if not all(
        isinstance(value, str)
        and re.fullmatch(r"[0-9a-f]{40}", value) is not None
        and value != "0" * 40
        for value in runtime_identities
    ):
        raise MaterializationError("M38 runtime repair identities are not sealed")
    expected_placeholder_blobs = {
        path: f"PENDING_M38_INITIAL_CONTROL_BLOB_{index}"
        for index, path in enumerate(
            sorted(_M38_OPERATOR_CONTROL_PATHS), start=1
        )
    }
    control_identities = (
        _M38_INITIAL_CONTROL_COMMIT,
        _M38_INITIAL_CONTROL_TREE,
        *tuple(_M38_INITIAL_CONTROL_BLOBS.values()),
    )
    if (
        _M38_INITIAL_CONTROL_COMMIT == "PENDING_M38_INITIAL_CONTROL_COMMIT"
        and _M38_INITIAL_CONTROL_TREE == "PENDING_M38_INITIAL_CONTROL_TREE"
        and dict(_M38_INITIAL_CONTROL_BLOBS) == expected_placeholder_blobs
    ):
        return True
    if all(
        isinstance(value, str)
        and re.fullmatch(r"[0-9a-f]{40}", value) is not None
        and value != "0" * 40
        for value in control_identities
    ):
        return False
    raise MaterializationError(
        "M38 initial-control identities mix placeholder and sealed values"
    )


