def _m43_authority_reference() -> dict[str, Any]:
    """Return M43's sealed authority reference and reject body drift."""

    authority = _expected_m43_dead_attempt_lifecycle_recovery_restart_authority()
    if not _M43_AUTHORITY_CID.endswith("PENDING_M43_FINAL_CONTROL_AUTHORITY_CID"):
        if _identity(authority) != _M43_AUTHORITY_CID:
            raise MaterializationError("M43 source successor authority CID differs")
    return {
        "schema": "sawm/operator-control-authority-reference@1",
        "migration_revision": _M43_MIGRATION_REVISION,
        "authority_cid": _M43_AUTHORITY_CID,
    }


def _validated_m43_live_preflight_contract(
    authority: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Validate M43's closed generation-30 to generation-31 contract."""

    expected = _expected_m43_dead_attempt_lifecycle_recovery_restart_authority()
    contract = authority.get("live_preflight_contract")
    repair = authority.get("accepted_lifecycle_repair")
    failed_validation = authority.get(
        "failed_pre_authoritative_control_validation"
    )
    fixture_repair = authority.get("accepted_historical_fixture_repair")
    failed_reseal_validation = authority.get(
        "failed_pre_authoritative_reseal_validation"
    )
    verifier_repair = authority.get(
        "accepted_bounded_materializer_verifier_repair"
    )
    prior_revision3 = authority.get("prior_revision3_authority")
    validation_attempts = authority.get("revision4_validation_attempts")
    successor_verifier_repair = authority.get(
        "accepted_successor_evidence_verifier_repair"
    )
    final_hardening = authority.get("final_control_hardening")
    prior_control = authority.get("prior_control_authorization")
    receipt = authority.get("preserved_m42_receipt")
    if (
        dict(authority) != expected
        or not isinstance(contract, Mapping)
        or not isinstance(repair, Mapping)
        or not isinstance(failed_validation, Mapping)
        or not isinstance(fixture_repair, Mapping)
        or not isinstance(failed_reseal_validation, Mapping)
        or not isinstance(verifier_repair, Mapping)
        or not isinstance(prior_revision3, Mapping)
        or not isinstance(validation_attempts, Mapping)
        or not isinstance(successor_verifier_repair, Mapping)
        or not isinstance(final_hardening, Mapping)
        or not isinstance(prior_control, Mapping)
        or not isinstance(receipt, Mapping)
        or authority.get("schema")
        != "sawm/dead-attempt-lifecycle-recovery-restart-authorization@4"
        or authority.get("authorization_revision") != 4
        or authority.get("authorization_amended_at")
        != _M43_AUTHORIZATION_AMENDED_AT
        or authority.get("prior_authorization_cid")
        != _M43_REVISION3_AUTHORITY_CID
        or authority.get("authorization_amendment_paths")
        != sorted(_M43_OPERATOR_CONTROL_PATHS)
        or prior_control.get("authorization_cid")
        != _M43_REVISION3_AUTHORITY_CID
        or prior_control.get("authorization_revision") != 3
        or prior_control.get("prior_authorization_cid")
        != _M43_PRIOR_FINAL_AUTHORITY_CID
        or prior_control.get("control_recorded_at")
        != _M43_REVISION3_CONTROL_RECORDED_AT
        or prior_control.get("control_commit")
        != _M43_REVISION3_FINAL_CONTROL_COMMIT
        or prior_control.get("control_tree")
        != _M43_REVISION3_FINAL_CONTROL_TREE
        or prior_control.get("superseded_before_authoritative_event_297")
        is not True
        or prior_control.get("event_297_appended") is not False
        or prior_control.get("receipt_published") is not False
        or dict(prior_revision3) != _expected_m43_revision3_authority()
        or _identity(prior_revision3) != _M43_REVISION3_AUTHORITY_CID
        or dict(validation_attempts) != _m43_revision4_validation_attempts()
        or validation_attempts.get("observed_failure_count") != 1
        or validation_attempts.get("worker_self_approval") is not False
        or dict(successor_verifier_repair)
        != _m43_successor_evidence_verifier_repair()
        or successor_verifier_repair.get("repair_parent")
        != _M43_REVISION3_FINAL_CONTROL_COMMIT
        or successor_verifier_repair.get("repair_commit")
        != _M43_SUCCESSOR_EVIDENCE_VERIFIER_REPAIR_COMMIT
        or successor_verifier_repair.get("repair_tree")
        != _M43_SUCCESSOR_EVIDENCE_VERIFIER_REPAIR_TREE
        or successor_verifier_repair.get("binary_diff_sha256")
        != _M43_SUCCESSOR_EVIDENCE_VERIFIER_REPAIR_DIFF_SHA256
        or successor_verifier_repair.get("blob_oids")
        != dict(_M43_SUCCESSOR_EVIDENCE_VERIFIER_REPAIR_BLOBS)
        or successor_verifier_repair.get("path_modes")
        != dict(_M43_SUCCESSOR_EVIDENCE_VERIFIER_REPAIR_MODES)
        or successor_verifier_repair.get("unlisted_extra_evidence_rejected")
        is not True
        or successor_verifier_repair.get("m42_return_counts_changed")
        is not False
        or successor_verifier_repair.get("authority_weakened") is not False
        or contract.get("migration_revision") != _M43_MIGRATION_REVISION
        or contract.get("prior_generation") != _M43_PRIOR_GENERATION
        or contract.get("target_generation") != _M43_TARGET_GENERATION
        or contract.get("prior_event_watermark") != _M43_PRIOR_EVENT_WATERMARK
        or contract.get("target_event_watermark") != _M43_TARGET_EVENT_WATERMARK
        or contract.get("prior_projection_cid") != _M43_PRIOR_PROJECTION_CID
        or contract.get("target_projection_cid") != _M43_TARGET_PROJECTION_CID
        or contract.get("m42_receipt_must_be_preserved") is not True
        or contract.get("generation_restart_authorized") is not True
        or receipt.get("receipt_cid") != _M43_M42_RECEIPT_CID
        or repair.get("newest_first_attempt_selection") is not True
        or repair.get("authority_weakened") is not False
        or failed_validation.get("failed_test_ids")
        != list(_M43_FAILED_TEST_IDS)
        or failed_validation.get("authenticated_mutation_request_created")
        is not False
        or fixture_repair.get("focused_replay_is_full_suite") is not False
        or fixture_repair.get(
            "fixture_collection_or_selection_logic_changed"
        )
        is not False
        or fixture_repair.get("validation_weakened") is not False
        or failed_reseal_validation.get("authority_cid")
        != _M43_PRIOR_FINAL_AUTHORITY_CID
        or failed_reseal_validation.get("control_commit")
        != _M43_PRIOR_FINAL_CONTROL_COMMIT
        or failed_reseal_validation.get("control_tree")
        != _M43_PRIOR_FINAL_CONTROL_TREE
        or failed_reseal_validation.get("observed_failure_count") != 2
        or failed_reseal_validation.get("isolated_live_rehearsal", {}).get(
            "disposable_generation_31_ready"
        )
        is not True
        or failed_reseal_validation.get("full_suite_validation", {}).get(
            "error"
        )
        != "MigrationRequired: operator task-recovery event differs"
        or failed_reseal_validation.get("authoritative_materializer_invoked")
        is not False
        or failed_reseal_validation.get("authenticated_mutation_request_created")
        is not False
        or failed_reseal_validation.get("event_297_rows_created") != 0
        or failed_reseal_validation.get("accepted_completion_changes") != 0
        or verifier_repair.get("repair_parent")
        != _M43_PRIOR_FINAL_CONTROL_COMMIT
        or verifier_repair.get("repair_commit") != _M43_VERIFIER_REPAIR_COMMIT
        or verifier_repair.get("repair_tree") != _M43_VERIFIER_REPAIR_TREE
        or verifier_repair.get("changed_paths")
        != sorted(_M43_VERIFIER_REPAIR_BLOBS)
        or verifier_repair.get("blob_oids")
        != dict(_M43_VERIFIER_REPAIR_BLOBS)
        or verifier_repair.get("path_modes")
        != dict(_M43_VERIFIER_REPAIR_MODES)
        or verifier_repair.get("repair_class_count") != 2
        or verifier_repair.get("repair_classes")
        != [
            "duckdb_positional_row_normalization",
            "task_revision_timestamp_source_binding",
        ]
        or verifier_repair.get("repair_site_count") != 5
        or verifier_repair.get("repair_sites")
        != [
            "m43_operational_suffix_rows",
            "m43_prestart_event_type_counts",
            "m43_live_preappend_event_type_counts",
            "m43_live_postappend_event_type_counts",
            "m6_recovery_revision_recorded_at",
        ]
        or verifier_repair.get("expected_values_changed") is not False
        or verifier_repair.get("validation_weakened") is not False
        or verifier_repair.get("authority_weakened") is not False
        or verifier_repair.get("database_mutations") != 0
        or verifier_repair.get("event_append_changes") != 0
        or verifier_repair.get("accepted_completion_changes") != 0
        or final_hardening.get(
            "operational_suffix_malformed_rows_are_typed_conflicts"
        )
        is not True
        or final_hardening.get("pending_authority_rejected_by_operator_facade")
        is not True
        or final_hardening.get(
            "exact_successor_evidence_is_the_only_postappend_allowance"
        )
        is not True
        or final_hardening.get("m42_return_contract_preserved") is not True
        or final_hardening.get(
            "unlisted_physical_evidence_still_fails_closed"
        )
        is not True
        or final_hardening.get("current_commit_identity_embedded_in_authority")
        is not False
        or final_hardening.get("authority_weakened") is not False
    ):
        raise MaterializationError("M43 live preflight contract differs")
    return contract


