def _m21_successor_configured(config: Mapping[str, Any]) -> bool:
    """Select a key-present M21 successor before every predecessor."""

    key = "generation_realization_successor_materialization"
    if key not in config:
        return False
    if config.get(key) != _expected_m21_generation_realization_authority():
        raise MaterializationError(
            "M21 generation-realization authority is invalid"
        )
    return True


