def _assert_m44_source_delta(
    root: Path,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> None:
    """Require de286 -> exact b213 repair -> one nine-control child."""

    identities = (
        _M44_M43_FINAL_CONTROL_COMMIT,
        _M44_M43_FINAL_CONTROL_TREE,
        *tuple(_M44_M43_FINAL_CONTROL_BLOBS.values()),
        _M44_REPAIR_COMMIT,
        _M44_REPAIR_TREE,
        *tuple(_M44_REPAIR_BLOBS.values()),
    )
    if (
        any(re.fullmatch(r"[0-9a-f]{40}", value) is None for value in identities)
        or _M44_AUTHORITY_CID.endswith("PENDING_M44_FINAL_CONTROL_AUTHORITY_CID")
    ):
        raise MaterializationError("M44 final control identities are not resealed")
    current = str(population["source_binding"]["head"])
    chain = authority.get("source_chain")
    controls = set(authority.get("operator_control_paths") or ())
    repairs = set(_M44_REPAIR_BLOBS)
    repair_parents = _git(
        root, "rev-list", "--parents", "-n", "1", _M44_REPAIR_COMMIT
    ).split()
    current_parents = _git(
        root, "rev-list", "--parents", "-n", "1", current
    ).split()
    binary_diff = subprocess.run(
        [
            "git",
            "diff",
            "--binary",
            _M44_REPAIR_PARENT,
            _M44_REPAIR_COMMIT,
            "--",
            *sorted(repairs),
        ],
        cwd=root,
        check=False,
        stdin=subprocess.DEVNULL,
        capture_output=True,
        timeout=20,
    )
    if binary_diff.returncode:
        raise MaterializationError("M44 repair binary diff is unavailable")
    observed_diff_sha256 = hashlib.sha256(binary_diff.stdout).hexdigest()
    if (
        current in {_M44_M43_FINAL_CONTROL_COMMIT, _M44_REPAIR_COMMIT}
        or not isinstance(chain, Mapping)
        or controls != set(_M44_OPERATOR_CONTROL_PATHS)
        or _M44_OPERATOR_CONTROL_PATHS != _M43_OPERATOR_CONTROL_PATHS
        or chain.get("m43_final_control_commit")
        != _M44_M43_FINAL_CONTROL_COMMIT
        or chain.get("m43_final_control_tree") != _M44_M43_FINAL_CONTROL_TREE
        or chain.get("m43_final_control_blobs")
        != dict(_M44_M43_FINAL_CONTROL_BLOBS)
        or chain.get("m43_final_control_modes")
        != dict(_M44_M43_FINAL_CONTROL_MODES)
        or chain.get("repair_parent") != _M44_REPAIR_PARENT
        or chain.get("repair_commit") != _M44_REPAIR_COMMIT
        or chain.get("repair_tree") != _M44_REPAIR_TREE
        or chain.get("repair_diff_sha256") != _M44_REPAIR_DIFF_SHA256
        or chain.get("repair_blobs") != dict(_M44_REPAIR_BLOBS)
        or chain.get("repair_modes") != dict(_M44_REPAIR_MODES)
        or chain.get("final_control_parent") != _M44_REPAIR_COMMIT
        or int(chain.get("repair_commit_count") or 0) != 1
        or int(chain.get("final_control_commit_count") or 0) != 1
        or chain.get("current_commit_identity_embedded_in_authority") is not False
        or repair_parents != [_M44_REPAIR_COMMIT, _M44_REPAIR_PARENT]
        or current_parents != [current, _M44_REPAIR_COMMIT]
        or _git(
            root, "rev-parse", f"{_M44_M43_FINAL_CONTROL_COMMIT}^{{tree}}"
        )
        != _M44_M43_FINAL_CONTROL_TREE
        or _git(root, "rev-parse", f"{_M44_REPAIR_COMMIT}^{{tree}}")
        != _M44_REPAIR_TREE
        or _m27_name_status(
            root, _M44_M43_FINAL_CONTROL_COMMIT, _M44_REPAIR_COMMIT
        )
        != {path: "M" for path in repairs}
        or _m27_name_status(root, _M44_REPAIR_COMMIT, current)
        != {path: "M" for path in controls}
        or observed_diff_sha256 != _M44_REPAIR_DIFF_SHA256
        or population["source_binding"].get("tree")
        != _git(root, "rev-parse", f"{current}^{{tree}}")
        or int(authority.get("ordinary_source_changes", -1)) != len(repairs)
    ):
        raise MaterializationError("M44 exact repair/control source chain differs")
    for commit, blobs, modes, noun in (
        (
            _M44_M43_FINAL_CONTROL_COMMIT,
            _M44_M43_FINAL_CONTROL_BLOBS,
            _M44_M43_FINAL_CONTROL_MODES,
            "M43-final-control",
        ),
        (_M44_REPAIR_COMMIT, _M44_REPAIR_BLOBS, _M44_REPAIR_MODES, "repair"),
    ):
        for path, oid in blobs.items():
            if _git(root, "rev-parse", f"{commit}:{path}") != oid:
                raise MaterializationError(f"M44 {noun} blob differs: {path}")
            if (
                _git(root, "ls-tree", commit, "--", path)
                != f"{modes[path]} blob {oid}\t{path}"
            ):
                raise MaterializationError(f"M44 {noun} mode differs: {path}")
    _assert_m43_current_control_modes(root, current, controls)
    for dependency, gitlink_key, tree_key, population_key in (
        (
            "ipfs_datasets_py",
            "current_datasets_gitlink",
            "current_datasets_tree",
            "datasets_gitlink",
        ),
        ("ipfs_kit_py", "current_kit_gitlink", "current_kit_tree", "kit_gitlink"),
    ):
        gitlink = str(authority[gitlink_key])
        if (
            any(
                _git(root, "rev-parse", f"{head}:{dependency}") != gitlink
                for head in (
                    _M44_M43_FINAL_CONTROL_COMMIT,
                    _M44_REPAIR_COMMIT,
                    current,
                )
            )
            or population["source_binding"].get(population_key) != gitlink
            or _git(root / dependency, "rev-parse", f"{gitlink}^{{tree}}")
            != authority[tree_key]
        ):
            raise MaterializationError(f"M44 {dependency} authority differs")


def _m44_target_paths(
    root: Path,
    config: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[Path, Path]:
    runtime = authority["runtime_binding"]
    program = config.get("database_program")
    owner = config.get("quack_owner")
    expected_runtime_paths = {
        "root": _M44_RUNTIME_ROOT,
        "state": f"{_M44_RUNTIME_ROOT}/state",
        "worktrees": _M44_WORKTREE_ROOT,
        "merge_queue": f"{_M44_RUNTIME_ROOT}/merge-queue",
        "logs": f"{_M44_RUNTIME_ROOT}/logs",
        "generated_runtime_artifacts_are_completion_authority": False,
    }
    if (
        not isinstance(program, Mapping)
        or not isinstance(owner, Mapping)
        or program.get("store_id") != _M44_STORE_ID
        or program.get("store_generation") != str(_M44_TARGET_GENERATION)
        or program.get("quack_endpoint") != runtime["quack_endpoint"]
        or program.get("worktree_root") != _M44_WORKTREE_ROOT
        or owner.get("database_path") != _M44_STORE_ID
        or owner.get("store_id") != _M44_STORE_ID
        or owner.get("port") != _M44_TARGET_QUACK_PORT
        or owner.get("state_dir") != f"{_M44_RUNTIME_ROOT}/quack-owner"
        or config.get("runtime_paths") != expected_runtime_paths
    ):
        raise MaterializationError("scheduler M44 runtime binding differs")
    control = (root / _M44_STORE_ID).resolve()
    coordination = (root / _M44_COORDINATION_STORE_ID).resolve()
    if not control.is_relative_to(root) or not coordination.is_relative_to(root):
        raise MaterializationError("M44 runtime path escapes repository")
    return control, coordination


