def _verify_m44_preserved_m43_receipt(
    root: Path, control: Path
) -> dict[str, Any]:
    """Re-hash the immutable M43 source-seal marker independently."""

    path = control.parent / "m43-source-successor-receipt.json"
    observed, observed_sha = _load_nofollow_json(
        path, root=root, noun="M44 preserved M43 source successor receipt"
    )
    try:
        receipt_stat = path.stat(follow_symlinks=False)
    except OSError as exc:
        raise MigrationRequired("M44 preserved M43 receipt is unavailable") from exc
    unhashed = dict(observed)
    claimed = str(unhashed.pop("receipt_cid", ""))
    if (
        observed_sha != _M44_M43_RECEIPT_SHA256
        or int(receipt_stat.st_size) != _M44_M43_RECEIPT_SIZE
        or stat.S_IMODE(receipt_stat.st_mode) != 0o600
        or claimed != _M44_M43_RECEIPT_CID
        or claimed != _identity(unhashed)
        or observed.get("migration_revision") != _M43_MIGRATION_REVISION
        or observed.get(f"{_M43_SUPERSESSION_REASON}_cid")
        != _M44_M43_AUTHORITY_CID
        or observed.get("current_source_binding_cid")
        != _M44_M43_SOURCE_BINDING_CID
        or observed.get("target_generation") != _M44_PRIOR_GENERATION
        or observed.get("target_event_watermark") != _M43_TARGET_EVENT_WATERMARK
        or observed.get("migration_evidence_event_id") != _M44_M43_EVENT_ID
        or observed.get("migration_evidence_id") != _M44_M43_EVIDENCE_ID
        or observed.get("target_event_prefix_sha256")
        != _M44_M43_EVENT_PREFIX_SHA256
        or observed.get("projection_cid") != _M43_TARGET_PROJECTION_CID
        or observed.get("control_database_is_authority") is not True
        or observed.get("authoritative") is not False
        or observed.get("worker_self_approval") is not False
    ):
        raise MigrationRequired("M44 preserved M43 receipt differs")
    return observed


def _verify_m44_preserved_m43_materialization(
    connection: Any,
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    """Re-hash M43's event-297/evidence rows from the preserved receipt."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    evidence = connection.execute(
        "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
        "created_at,body_json FROM evidence_nodes WHERE evidence_id=?",
        [_M44_M43_EVIDENCE_ID],
    ).fetchone()
    event = connection.execute(
        "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
        "attempt_id,session_id,recorded_at,body_json FROM domain_events "
        "WHERE global_sequence=?",
        [_M43_TARGET_EVENT_WATERMARK],
    ).fetchone()
    if evidence is None or event is None:
        raise MigrationRequired("M44 preserved M43 event/evidence is missing")
    normalized_evidence = _positional_rows([evidence], 7)[0]
    normalized_event = _positional_rows([event], 10)[0]
    body = _m38_parse_json(normalized_evidence[6])
    envelope = _m38_parse_json(normalized_event[9])
    digest = str(receipt.get("migration_digest") or "")
    expected_inner = {
        "evidence_id": _M44_M43_EVIDENCE_ID,
        "parent_evidence_id": "",
        "task_cid": _M42_OPERATOR_TASK_CID,
        "evidence_kind": _M43_EVIDENCE_KIND,
        "digest": digest,
        "body": body,
        "created_at": _M43_CONTROL_RECORDED_AT,
        "revision": 0,
    }
    expected_envelope = {
        "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
        "event_type": "intent.evidence_recorded",
        "subject_id": _M44_M43_EVIDENCE_ID,
        "body": expected_inner,
        "recorded_at": _M43_CONTROL_RECORDED_AT,
        "owner_id": "sawm-r2-m43-live-source-sealer",
    }
    rehashed_evidence_id = content_identity(
        {
            "task_cid": _M42_OPERATOR_TASK_CID,
            "evidence_kind": _M43_EVIDENCE_KIND,
            "digest": digest,
            "body": body,
        }
    )
    rehashed_event_id = content_identity(
        {
            "stream_id": "stream:intent",
            "sequence": _M43_TARGET_EVENT_WATERMARK,
            "global_sequence": _M43_TARGET_EVENT_WATERMARK,
            "event_type": "intent.evidence_recorded",
            "body": expected_envelope,
        }
    )
    if (
        tuple(normalized_evidence[:6])
        != (
            _M44_M43_EVIDENCE_ID,
            "",
            _M42_OPERATOR_TASK_CID,
            _M43_EVIDENCE_KIND,
            digest,
            _M43_CONTROL_RECORDED_AT,
        )
        or _identity(body) != digest
        or rehashed_evidence_id != _M44_M43_EVIDENCE_ID
        or tuple(normalized_event[:9])
        != (
            _M44_M43_EVENT_ID,
            "stream:intent",
            _M43_TARGET_EVENT_WATERMARK,
            _M43_TARGET_EVENT_WATERMARK,
            "intent.evidence_recorded",
            _M42_OPERATOR_TASK_CID,
            "",
            "session:intent",
            _M43_CONTROL_RECORDED_AT,
        )
        or envelope != expected_envelope
        or rehashed_event_id != _M44_M43_EVENT_ID
        or _event_prefix_digest(connection, _M43_TARGET_EVENT_WATERMARK)
        != (_M44_M43_EVENT_PREFIX_SHA256, _M43_TARGET_EVENT_WATERMARK)
    ):
        raise MigrationRequired("M44 preserved M43 event/evidence differs")
    return {
        "m43_event_297_preserved_exactly": True,
        "m43_event_id": _M44_M43_EVENT_ID,
        "m43_evidence_id": _M44_M43_EVIDENCE_ID,
    }


def _m44_operational_suffix_on(connection: Any) -> list[dict[str, Any]]:
    """Normalize the exact accepted event suffix 298 through 301."""

    try:
        rows = _positional_rows(
            connection.execute(
                "SELECT event_id,global_sequence,body_json FROM domain_events "
                "WHERE global_sequence>? AND global_sequence<=? "
                "ORDER BY global_sequence",
                [_M43_TARGET_EVENT_WATERMARK, _M44_PRIOR_EVENT_WATERMARK],
            ).fetchall(),
            3,
        )
    except (IndexError, KeyError, TypeError) as exc:
        raise MigrationRequired("M44 post-M43 event row is malformed") from exc
    normalized: list[dict[str, Any]] = []
    for event_id, sequence, raw_body in rows:
        try:
            envelope = _m38_parse_json(raw_body)
            normalized_sequence = int(sequence)
        except (json.JSONDecodeError, TypeError, ValueError) as exc:
            raise MigrationRequired("M44 post-M43 event row is malformed") from exc
        inner = envelope.get("body") if isinstance(envelope, Mapping) else None
        receipt = inner.get("receipt") if isinstance(inner, Mapping) else None
        if not isinstance(receipt, Mapping):
            raise MigrationRequired("M44 post-M43 event receipt is invalid")
        try:
            normalized_revision = int(inner.get("revision") or 0)
        except (TypeError, ValueError) as exc:
            raise MigrationRequired("M44 post-M43 event row is malformed") from exc
        normalized.append(
            {
                "global_sequence": normalized_sequence,
                "event_id": str(event_id),
                "task_alias": str(inner.get("task_alias") or ""),
                "status": str(inner.get("status") or ""),
                "revision": normalized_revision,
                "attempt_id": str(receipt.get("attempt_id") or ""),
                "claim_id": str(receipt.get("claim_id") or ""),
                "lease_id": str(receipt.get("lease_id") or ""),
                "operation": str(receipt.get("operation") or ""),
            }
        )
    return normalized


