def _ensure_m37_source_successor_receipt(
    root: Path, control: Path, expected: Mapping[str, Any]
) -> Mapping[str, Any]:
    path = control.parent / "m37-source-successor-receipt.json"
    lock_path = control.parent / ".m37-source-successor-receipt.publish.lock"
    descriptor = os.open(
        lock_path,
        os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0),
        0o600,
    )
    try:
        fcntl.flock(descriptor, fcntl.LOCK_EX)
        if os.path.lexists(path):
            observed, _ = _load_nofollow_json(
                path, root=root, noun="M37 source successor receipt"
            )
            if observed != dict(expected):
                raise MigrationRequired("M37 source successor receipt differs")
            return dict(observed)
        temporary = path.with_name(f".{path.name}.{os.getpid()}.tmp")
        out = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0),
            0o600,
        )
        try:
            os.write(out, _canonical(expected) + b"\n")
            os.fsync(out)
        finally:
            os.close(out)
        os.replace(temporary, path)
        directory = os.open(path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
        return dict(expected)
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        except OSError:
            pass
        os.close(descriptor)


def _m38_sql_triples(rows: Any, names: tuple[str, str, str]) -> list[tuple[Any, Any, Any]]:
    """Normalize Quack dict rows and native tuples to positional triples."""

    triples: list[tuple[Any, Any, Any]] = []
    for row in rows:
        if isinstance(row, Mapping):
            triples.append((row[names[0]], row[names[1]], row[names[2]]))
        else:
            triples.append((row[0], row[1], row[2]))
    return triples


def _m38_row_values(row: Any) -> tuple[Any, ...]:
    if isinstance(row, Mapping):
        return tuple(row.values())
    return tuple(row)


def _m38_parse_json(value: Any) -> Any:
    if isinstance(value, Mapping):
        return value
    if isinstance(value, (bytes, bytearray)):
        return json.loads(value.decode("utf-8"))
    return json.loads(str(value))


