def _m42_projection_row_identity(
    schema: str,
    columns: tuple[str, ...],
    row: tuple[Any, ...],
) -> str:
    if len(columns) != len(row):
        raise MigrationRequired("M42 legacy projection row shape is invalid")
    return _identity({"schema": schema, **dict(zip(columns, row, strict=True))})


def _m42_legacy_projection_manifest() -> dict[str, Any]:
    return {
        "schema": _M42_LEGACY_PROJECTION_MANIFEST_SCHEMA,
        "event_watermark": _M42_LEGACY_PROJECTION_WATERMARK,
        "evidence_node_count": _M42_LEGACY_EVIDENCE_NODE_COUNT,
        "evidence_event_count": _M42_LEGACY_EVIDENCE_EVENT_COUNT,
        "validation_event_count": _M42_LEGACY_VALIDATION_EVENT_COUNT,
        "passed_validation_event_count": (
            _M42_LEGACY_PASSED_VALIDATION_EVENT_COUNT
        ),
        "validation_evidence_node_count": (
            _M42_LEGACY_VALIDATION_EVIDENCE_NODE_COUNT
        ),
        "evidence_refresh_rows": [
            {
                "evidence_id": evidence_id,
                "source_created_at": control["source_created_at"],
                "target_created_at": _M42_LEGACY_EVIDENCE_REFRESHED_AT,
                "source_row_cid": control["source_row_cid"],
                "target_row_cid": control["target_row_cid"],
            }
            for evidence_id, control in sorted(
                _M42_LEGACY_EVIDENCE_REFRESH_ROWS.items()
            )
        ],
        "compact_validation_evidence": {
            key: (
                dict(value)
                if isinstance(value, Mapping)
                else value
            )
            for key, value in _M42_LEGACY_COMPACT_VALIDATION_EVIDENCE.items()
        },
        "validation_run_overlay": dict(_M42_LEGACY_VALIDATION_RUN_OVERLAY),
    }


def _m42_apply_exact_legacy_evidence_overlay(
    rows: Sequence[tuple[Any, ...]],
    *,
    watermark: int,
) -> list[tuple[Any, ...]]:
    """Apply only M42's sealed ten-row historical evidence overlay."""

    if int(watermark) != _M42_LEGACY_PROJECTION_WATERMARK:
        raise MigrationRequired("M42 legacy evidence overlay watermark differs")
    if _identity(_m42_legacy_projection_manifest()) != (
        _M42_LEGACY_PROJECTION_MANIFEST_CID
    ):
        raise MaterializationError("M42 legacy projection manifest CID differs")
    evidence_columns = (
        "evidence_id",
        "parent_evidence_id",
        "task_cid",
        "evidence_kind",
        "digest",
        "created_at",
        "body_json",
    )
    if len(rows) != _M42_LEGACY_EVIDENCE_NODE_COUNT:
        raise MigrationRequired("M42 legacy evidence source count differs")
    if any(len(row) != len(evidence_columns) for row in rows):
        raise MigrationRequired("M42 legacy evidence source row shape differs")
    by_id = {str(row[0]): tuple(row) for row in rows}
    if len(by_id) != len(rows):
        raise MigrationRequired("M42 legacy evidence source identities duplicate")
    required = set(_M42_LEGACY_EVIDENCE_REFRESH_ROWS) | {
        str(_M42_LEGACY_COMPACT_VALIDATION_EVIDENCE["evidence_id"])
    }
    if not required.issubset(by_id):
        raise MigrationRequired("M42 legacy evidence overlay is partial")

    transformed = dict(by_id)
    for evidence_id, control in _M42_LEGACY_EVIDENCE_REFRESH_ROWS.items():
        source = transformed[evidence_id]
        if (
            source[5] != control["source_created_at"]
            or _m42_projection_row_identity(
                "sawm/evidence-projection-row@1", evidence_columns, source
            )
            != control["source_row_cid"]
        ):
            raise MigrationRequired(
                "M42 legacy evidence refresh source row differs"
            )
        target = source[0:5] + (_M42_LEGACY_EVIDENCE_REFRESHED_AT,) + source[6:]
        if _m42_projection_row_identity(
            "sawm/evidence-projection-row@1", evidence_columns, target
        ) != control["target_row_cid"]:
            raise MaterializationError(
                "M42 legacy evidence refresh target row differs"
            )
        transformed[evidence_id] = target

    compact = _M42_LEGACY_COMPACT_VALIDATION_EVIDENCE
    compact_id = str(compact["evidence_id"])
    source = transformed[compact_id]
    try:
        source_body = _m38_parse_json(source[6])
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise MigrationRequired(
            "M42 compact validation evidence source body is invalid"
        ) from exc
    if (
        _identity(source_body) != compact["source_body_cid"]
        or _m42_projection_row_identity(
            "sawm/evidence-projection-row@1", evidence_columns, source
        )
        != compact["source_row_cid"]
    ):
        raise MigrationRequired(
            "M42 compact validation evidence source row differs"
        )
    target_body = dict(compact["target_body"])
    if _identity(target_body) != compact["target_body_cid"]:
        raise MaterializationError(
            "M42 compact validation evidence target body differs"
        )
    target = source[0:6] + (_canonical(target_body).decode("utf-8"),)
    if _m42_projection_row_identity(
        "sawm/evidence-projection-row@1", evidence_columns, target
    ) != compact["target_row_cid"]:
        raise MaterializationError(
            "M42 compact validation evidence target row differs"
        )
    transformed[compact_id] = target
    return sorted(transformed.values(), key=lambda row: str(row[0]))


def _m39_exact_row_matches(
    row: Any,
    columns: tuple[str, ...],
    expected: tuple[Any, ...],
) -> bool:
    """Compare a Quack row by selected column name and canonical JSON body.

    Quack may return tuples or mappings, and JSON values may already be decoded
    or may arrive as text/bytes.  Mapping insertion order and representation of
    ``body_json`` are transport details, not authority-bearing row order.
    """

    if row is None or len(columns) != len(expected):
        return False
    try:
        if isinstance(row, Mapping):
            if set(row) != set(columns):
                return False
            values = tuple(row[column] for column in columns)
        else:
            values = tuple(row)
            if len(values) != len(columns):
                return False
        if values[:-1] != expected[:-1]:
            return False
        observed_body = _canonical(_m38_parse_json(values[-1])).decode("utf-8")
    except (KeyError, TypeError, ValueError, UnicodeError):
        return False
    return observed_body == expected[-1]


def _m38_projection_cid_at_watermark(source: Any, watermark: int) -> str:
    """Recompute the canonical snapshot projection with an explicit watermark."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    with source.intent._connection(write=False) as connection:
        objective_count = int(
            connection.execute("SELECT COUNT(*) FROM objectives").fetchone()[0]
        )
        goals = _m38_sql_triples(
            connection.execute(
                "SELECT goal_cid,status,revision FROM goals ORDER BY goal_cid"
            ).fetchall(),
            ("goal_cid", "status", "revision"),
        )
        plans = _m38_sql_triples(
            connection.execute(
                "SELECT plan_cid,status,revision FROM plans ORDER BY plan_cid"
            ).fetchall(),
            ("plan_cid", "status", "revision"),
        )
        tasks = _m38_sql_triples(
            connection.execute(
                "SELECT task_cid,status,revision FROM tasks ORDER BY task_cid"
            ).fetchall(),
            ("task_cid", "status", "revision"),
        )
        dependency_count = int(
            connection.execute("SELECT COUNT(*) FROM task_dependencies").fetchone()[0]
        )
    return content_identity(
        {
            "objectives": objective_count,
            "goals": [
                {
                    "goal_cid": str(goal_cid),
                    "status": str(status),
                    "revision": int(revision),
                }
                for goal_cid, status, revision in goals
            ],
            "plans": [
                {
                    "plan_cid": str(plan_cid),
                    "status": str(status),
                    "revision": int(revision),
                }
                for plan_cid, status, revision in plans
            ],
            "tasks": [
                {
                    "task_cid": str(task_cid),
                    "status": str(status),
                    "revision": int(revision),
                }
                for task_cid, status, revision in tasks
            ],
            "dependency_count": dependency_count,
            "event_watermark": int(watermark),
        }
    )


def _m38_evidence_projection_from_events(
    connection: Any,
    *,
    watermark: int,
) -> dict[str, Any]:
    """Fold the immutable event prefix into its exact evidence-node projection."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    event_rows = connection.execute(
        "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
        "attempt_id,session_id,recorded_at,body_json FROM domain_events "
        "WHERE global_sequence<=? AND event_type IN "
        "('intent.evidence_recorded','intent.validation_recorded') "
        "ORDER BY global_sequence",
        [int(watermark)],
    ).fetchall()

    projected: dict[str, tuple[tuple[str, ...], str]] = {}
    seen_sequences: set[int] = set()
    last_sequence = 0
    evidence_recorded_ids: set[str] = set()
    validation_evidence_ids: set[str] = set()
    evidence_event_count = 0
    validation_event_count = 0
    passed_validation_event_count = 0

    def closed_object(pairs: Sequence[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, member in pairs:
            if key in value:
                raise ValueError(f"duplicate event JSON key {key!r}")
            value[key] = member
        return value

    def require_text(value: Any, *, field: str, optional: bool = False) -> str:
        if not isinstance(value, str) or (not optional and not value):
            raise MigrationRequired(f"M38 evidence event {field} is invalid")
        return value

    def fold(row: tuple[str, ...], *, source_kind: str) -> None:
        evidence_id = row[0]
        previous = projected.get(evidence_id)
        if previous is not None:
            previous_row, previous_source = previous
            # Explicit evidence IDs exclude created_at from their identity and
            # record_evidence deliberately performs DELETE+INSERT.  Therefore
            # identical evidence may be refreshed and the greatest event
            # sequence supplies its current timestamp.  A validation evidence
            # ID includes run_id, whose identity binds its recorded_at; any
            # timestamp change involving a validation-derived row is a conflict.
            if previous_source == "validation" or source_kind == "validation":
                identity_matches = previous_row == row
            else:
                identity_matches = (
                    previous_row[0:5] + previous_row[6:7]
                    == row[0:5] + row[6:7]
                )
            if not identity_matches:
                raise MigrationRequired(
                    "M38 evidence event identity-bound fields conflict"
                )
        projected[evidence_id] = (row, source_kind)

    event_columns = (
        "event_id",
        "stream_id",
        "sequence",
        "global_sequence",
        "event_type",
        "task_cid",
        "attempt_id",
        "session_id",
        "recorded_at",
        "body_json",
    )
    for raw_row in event_rows:
        if isinstance(raw_row, Mapping):
            if any(column not in raw_row for column in event_columns):
                raise MigrationRequired("M38 evidence event row shape is invalid")
            normalized_row = tuple(raw_row[column] for column in event_columns)
        else:
            try:
                normalized_row = tuple(raw_row[index] for index in range(10))
            except (IndexError, KeyError, TypeError) as exc:
                raise MigrationRequired(
                    "M38 evidence event row shape is invalid"
                ) from exc
            if len(raw_row) != 10:
                raise MigrationRequired("M38 evidence event row shape is invalid")
        (
            event_id,
            stream_id,
            stream_sequence,
            global_sequence,
            event_type,
            task_cid,
            attempt_id,
            session_id,
            event_recorded_at,
            body_json,
        ) = normalized_row
        try:
            sequence = int(global_sequence)
            normalized_stream_sequence = int(stream_sequence)
        except (TypeError, ValueError) as exc:
            raise MigrationRequired("M38 evidence event sequence is invalid") from exc
        if (
            sequence < 1
            or sequence > int(watermark)
            or sequence in seen_sequences
            or sequence <= last_sequence
            or normalized_stream_sequence != sequence
        ):
            raise MigrationRequired("M38 evidence event sequence is invalid")
        seen_sequences.add(sequence)
        last_sequence = sequence
        encoded_envelope: str | None
        if isinstance(body_json, Mapping):
            envelope = dict(body_json)
            encoded_envelope = None
        else:
            if isinstance(body_json, bytes):
                try:
                    encoded_envelope = body_json.decode("utf-8")
                except UnicodeDecodeError as exc:
                    raise MigrationRequired("M38 evidence event JSON is invalid") from exc
            elif isinstance(body_json, str):
                encoded_envelope = body_json
            else:
                raise MigrationRequired("M38 evidence event JSON is invalid")
            try:
                envelope = json.loads(
                    encoded_envelope, object_pairs_hook=closed_object
                )
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise MigrationRequired("M38 evidence event JSON is invalid") from exc
        try:
            canonical_envelope = _canonical(envelope).decode("utf-8")
        except (TypeError, ValueError) as exc:
            raise MigrationRequired("M38 evidence event JSON is invalid") from exc
        if encoded_envelope is not None and encoded_envelope != canonical_envelope:
            raise MigrationRequired("M38 evidence event envelope differs")
        # Normalize Quack's decoded Mapping and local text transports to the
        # same plain, canonical JSON value before validation and rehashing.
        envelope = json.loads(canonical_envelope, object_pairs_hook=closed_object)
        if (
            not isinstance(envelope, Mapping)
            or set(envelope)
            != {
                "schema",
                "event_type",
                "subject_id",
                "body",
                "recorded_at",
                "owner_id",
            }
            or envelope.get("schema")
            != "ipfs_accelerate_py/agent-supervisor/intent-event@1"
            or envelope.get("event_type") != event_type
            or envelope.get("recorded_at") != event_recorded_at
            or stream_id != "stream:intent"
            or not isinstance(session_id, str)
            or not session_id
            or not isinstance(envelope.get("owner_id"), str)
            or not envelope.get("owner_id")
            or event_id
            != content_identity(
                {
                    "stream_id": "stream:intent",
                    "sequence": sequence,
                    "global_sequence": sequence,
                    "event_type": event_type,
                    "body": envelope,
                }
            )
        ):
            raise MigrationRequired("M38 evidence event envelope differs")
        inner = envelope.get("body") if isinstance(envelope, Mapping) else None
        if not isinstance(inner, Mapping):
            raise MigrationRequired("M38 evidence event envelope differs")

        if event_type == "intent.evidence_recorded":
            evidence_event_count += 1
            # ``record_evidence`` samples the evidence-node ``created_at``
            # before ``_append_event`` independently samples the outer event
            # ``recorded_at``.  A second boundary between those calls is
            # legitimate.  The inner time remains bound by the event CID and
            # is exact-matched to the projected evidence row below; the outer
            # time is independently bound to the domain-event row above.
            if (
                set(inner)
                != {
                    "evidence_id",
                    "parent_evidence_id",
                    "task_cid",
                    "evidence_kind",
                    "digest",
                    "body",
                    "created_at",
                    "revision",
                }
                or type(inner.get("revision")) is not int
                or inner.get("revision") != 0
                or attempt_id != ""
            ):
                raise MigrationRequired("M38 evidence event envelope differs")
            evidence_id = require_text(inner.get("evidence_id"), field="evidence_id")
            parent_evidence_id = require_text(
                inner.get("parent_evidence_id"),
                field="parent_evidence_id",
                optional=True,
            )
            inner_task_cid = require_text(inner.get("task_cid"), field="task_cid")
            evidence_kind = require_text(
                inner.get("evidence_kind"), field="evidence_kind"
            )
            digest = require_text(inner.get("digest"), field="digest")
            created_at = require_text(inner.get("created_at"), field="created_at")
            body = inner.get("body")
            if (
                not isinstance(body, Mapping)
                or envelope.get("subject_id") != evidence_id
                or task_cid != inner_task_cid
                or evidence_id
                != content_identity(
                    {
                        "task_cid": inner_task_cid,
                        "evidence_kind": evidence_kind,
                        "digest": digest,
                        "body": body,
                    }
                )
            ):
                raise MigrationRequired("M38 evidence event envelope differs")
            fold(
                (
                    evidence_id,
                    parent_evidence_id,
                    inner_task_cid,
                    evidence_kind,
                    digest,
                    created_at,
                    _canonical(body).decode("utf-8"),
                ),
                source_kind="evidence",
            )
            evidence_recorded_ids.add(evidence_id)
            continue

        if event_type != "intent.validation_recorded":
            raise MigrationRequired("M38 evidence event type is invalid")
        validation_event_count += 1
        if (
            set(inner)
            != {
                "result_id",
                "run_id",
                "task_cid",
                "outcome",
                "evidence_digest",
                "argv",
                "body",
                "recorded_at",
                "revision",
            }
            or type(inner.get("revision")) is not int
            or inner.get("revision") != 0
        ):
            raise MigrationRequired("M38 validation event envelope differs")
        result_id = require_text(inner.get("result_id"), field="result_id")
        run_id = require_text(inner.get("run_id"), field="run_id")
        inner_task_cid = require_text(inner.get("task_cid"), field="task_cid")
        outcome = require_text(inner.get("outcome"), field="outcome")
        digest = require_text(inner.get("evidence_digest"), field="evidence_digest")
        recorded_at = require_text(inner.get("recorded_at"), field="recorded_at")
        argv = inner.get("argv")
        validation_body = inner.get("body")
        # ``record_validation_result`` similarly samples the validation-run
        # time before ``_append_event`` samples the outer event time.  Bind
        # the former through ``run_id`` and the latter through the event CID;
        # do not require the two independently authoritative observations to
        # be textually equal.
        if (
            outcome not in {"passed", "failed", "error", "skipped"}
            or not isinstance(argv, list)
            or any(not isinstance(argument, str) for argument in argv)
            or not isinstance(validation_body, Mapping)
            or not isinstance(attempt_id, str)
            or envelope.get("subject_id") != result_id
            or task_cid != inner_task_cid
            or run_id
            != content_identity(
                {
                    "task_cid": inner_task_cid,
                    "attempt_id": attempt_id,
                    "argv": argv,
                    "recorded_at": recorded_at,
                }
            )
            or result_id
            != content_identity(
                {
                    "run_id": run_id,
                    "outcome": outcome,
                    "evidence_digest": digest,
                }
            )
        ):
            raise MigrationRequired("M38 validation event envelope differs")
        if outcome != "passed":
            continue
        passed_validation_event_count += 1
        evidence_id = content_identity(
            {
                "task_cid": inner_task_cid,
                "evidence_kind": "validation",
                "digest": digest,
                "run_id": run_id,
            }
        )
        fold(
            (
                evidence_id,
                "",
                inner_task_cid,
                "validation",
                digest,
                recorded_at,
                _canonical(
                    {
                        "run_id": run_id,
                        "result_id": result_id,
                        "argv": argv,
                        "outcome": "passed",
                    }
                ).decode("utf-8"),
            ),
            source_kind="validation",
        )
        validation_evidence_ids.add(evidence_id)

    expected_sorted = sorted(
        (value[0] for value in projected.values()), key=lambda row: row[0]
    )
    return {
        "rows": expected_sorted,
        "evidence_node_count": len(expected_sorted),
        "evidence_event_count": evidence_event_count,
        "evidence_recorded_node_count": len(evidence_recorded_ids),
        "validation_event_count": validation_event_count,
        "passed_validation_event_count": passed_validation_event_count,
        "validation_evidence_node_count": len(validation_evidence_ids),
    }


def _verify_m38_evidence_projection(
    connection: Any,
    *,
    watermark: int,
) -> dict[str, Any]:
    """Verify every evidence row against the immutable intent-event prefix."""

    projection = _m38_evidence_projection_from_events(
        connection, watermark=watermark
    )
    raw_actual = connection.execute(
        "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
        "created_at,body_json FROM evidence_nodes ORDER BY evidence_id"
    ).fetchall()
    evidence_columns = (
        "evidence_id",
        "parent_evidence_id",
        "task_cid",
        "evidence_kind",
        "digest",
        "created_at",
        "body_json",
    )
    actual: list[tuple[Any, ...]] = []
    for raw_row in raw_actual:
        if isinstance(raw_row, Mapping):
            if any(column not in raw_row for column in evidence_columns):
                raise MigrationRequired("M38 evidence-node row shape is invalid")
            row = tuple(raw_row[column] for column in evidence_columns)
        else:
            try:
                row = tuple(raw_row[index] for index in range(7))
            except (IndexError, KeyError, TypeError) as exc:
                raise MigrationRequired(
                    "M38 evidence-node row shape is invalid"
                ) from exc
            if len(raw_row) != 7:
                raise MigrationRequired("M38 evidence-node row shape is invalid")
        body_json = row[6]
        if isinstance(body_json, Mapping):
            body_text = _canonical(body_json).decode("utf-8")
        elif isinstance(body_json, bytes):
            try:
                body_text = body_json.decode("utf-8")
            except UnicodeDecodeError as exc:
                raise MigrationRequired("M38 evidence-node body is invalid") from exc
        elif isinstance(body_json, str):
            body_text = body_json
        else:
            raise MigrationRequired("M38 evidence-node body is invalid")
        actual.append(row[0:6] + (body_text,))
    expected_sorted = projection["rows"]
    if len({row[0] for row in actual}) != len(actual):
        raise MigrationRequired("M38 evidence-node identities are duplicate")
    actual_by_id = {row[0]: row for row in actual}
    expected_by_id = {row[0]: row for row in expected_sorted}
    missing = sorted(set(expected_by_id) - set(actual_by_id))
    extra = sorted(set(actual_by_id) - set(expected_by_id))
    if missing:
        raise MigrationRequired("M38 evidence-node projection is missing rows")
    if extra:
        raise MigrationRequired("M38 evidence-node projection has extra rows")
    if actual_by_id != expected_by_id:
        raise MigrationRequired("M38 evidence-node/event projection conflicts")
    return {
        key: value for key, value in projection.items() if key != "rows"
    } | {
        "evidence_projection_digest": _identity(
            {
                "watermark": int(watermark),
                "rows": expected_sorted,
                "evidence_event_count": projection["evidence_event_count"],
                "validation_event_count": projection["validation_event_count"],
                "passed_validation_event_count": projection[
                    "passed_validation_event_count"
                ],
            }
        ),
        "complete_evidence_projection_verified": True,
    }


def _m42_normalized_projection_rows(
    raw_rows: Sequence[Any],
    *,
    columns: tuple[str, ...],
    noun: str,
) -> list[tuple[Any, ...]]:
    """Normalize named Quack rows without weakening canonical JSON checks."""

    normalized: list[tuple[Any, ...]] = []
    for raw_row in raw_rows:
        if isinstance(raw_row, Mapping):
            if set(raw_row) != set(columns):
                raise MigrationRequired(f"M42 {noun} row shape differs")
            row = tuple(raw_row[column] for column in columns)
        else:
            try:
                row = tuple(raw_row[index] for index in range(len(columns)))
            except (IndexError, KeyError, TypeError) as exc:
                raise MigrationRequired(f"M42 {noun} row shape differs") from exc
            if len(raw_row) != len(columns):
                raise MigrationRequired(f"M42 {noun} row shape differs")
        encoded = row[-1]
        if isinstance(encoded, Mapping):
            canonical = _canonical(encoded).decode("utf-8")
        else:
            if isinstance(encoded, bytes):
                try:
                    text = encoded.decode("utf-8")
                except UnicodeDecodeError as exc:
                    raise MigrationRequired(f"M42 {noun} body is invalid") from exc
            elif isinstance(encoded, str):
                text = encoded
            else:
                raise MigrationRequired(f"M42 {noun} body is invalid")
            try:
                canonical = _canonical(_m38_parse_json(text)).decode("utf-8")
            except (TypeError, ValueError, json.JSONDecodeError) as exc:
                raise MigrationRequired(f"M42 {noun} body is invalid") from exc
            if text != canonical:
                raise MigrationRequired(f"M42 {noun} body is not canonical")
        normalized.append(row[:-1] + (canonical,))
    return normalized


def _m42_legacy_validation_table_projection(
    connection: Any,
) -> dict[str, Any]:
    """Verify all eleven validation rows plus the sole sealed attempt overlay."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    raw_events = connection.execute(
        "SELECT global_sequence,attempt_id,body_json FROM domain_events "
        "WHERE global_sequence<=? AND event_type='intent.validation_recorded' "
        "ORDER BY global_sequence",
        [_M42_LEGACY_PROJECTION_WATERMARK],
    ).fetchall()
    event_rows = _m42_normalized_projection_rows(
        raw_events,
        columns=("global_sequence", "attempt_id", "body_json"),
        noun="validation event projection",
    )
    if len(event_rows) != _M42_LEGACY_VALIDATION_EVENT_COUNT:
        raise MigrationRequired("M42 validation event projection count differs")

    run_columns = (
        "run_id",
        "task_cid",
        "attempt_id",
        "started_at",
        "finished_at",
        "status",
        "command_digest",
        "body_json",
    )
    result_columns = (
        "result_id",
        "run_id",
        "task_cid",
        "ordinal",
        "outcome",
        "evidence_digest",
        "body_json",
    )
    expected_runs: list[tuple[Any, ...]] = []
    expected_results: list[tuple[Any, ...]] = []
    overlay_seen = 0
    overlay = _M42_LEGACY_VALIDATION_RUN_OVERLAY
    for global_sequence, attempt_id, encoded_envelope in event_rows:
        envelope = _m38_parse_json(encoded_envelope)
        inner = envelope.get("body") if isinstance(envelope, Mapping) else None
        if not isinstance(inner, Mapping):
            raise MigrationRequired("M42 validation event body differs")
        argv = inner.get("argv")
        body = inner.get("body")
        if not isinstance(argv, list) or not isinstance(body, Mapping):
            raise MigrationRequired("M42 validation event body differs")
        source_run = (
            inner.get("run_id"),
            inner.get("task_cid"),
            attempt_id,
            inner.get("recorded_at"),
            inner.get("recorded_at"),
            inner.get("outcome"),
            content_identity({"argv": argv}),
            _canonical({"argv": argv, **dict(body)}).decode("utf-8"),
        )
        if int(global_sequence) == int(overlay["global_sequence"]):
            if (
                source_run[0] != overlay["run_id"]
                or source_run[2] != overlay["source_attempt_id"]
                or _m42_projection_row_identity(
                    "sawm/validation-run-projection-row@1",
                    run_columns,
                    source_run,
                )
                != overlay["source_row_cid"]
            ):
                raise MigrationRequired(
                    "M42 legacy validation-run source row differs"
                )
            source_run = source_run[0:2] + (overlay["target_attempt_id"],) + source_run[3:]
            if _m42_projection_row_identity(
                "sawm/validation-run-projection-row@1", run_columns, source_run
            ) != overlay["target_row_cid"]:
                raise MaterializationError(
                    "M42 legacy validation-run target row differs"
                )
            overlay_seen += 1
        expected_runs.append(source_run)
        expected_results.append(
            (
                inner.get("result_id"),
                inner.get("run_id"),
                inner.get("task_cid"),
                0,
                inner.get("outcome"),
                inner.get("evidence_digest"),
                _canonical(body).decode("utf-8"),
            )
        )
    if overlay_seen != 1:
        raise MigrationRequired("M42 legacy validation-run overlay is incomplete")

    actual_runs = _m42_normalized_projection_rows(
        connection.execute(
            "SELECT run_id,task_cid,attempt_id,started_at,finished_at,status,"
            "command_digest,body_json FROM validation_runs ORDER BY run_id"
        ).fetchall(),
        columns=run_columns,
        noun="validation_runs",
    )
    actual_results = _m42_normalized_projection_rows(
        connection.execute(
            "SELECT result_id,run_id,task_cid,ordinal,outcome,evidence_digest,"
            "body_json FROM validation_results ORDER BY result_id"
        ).fetchall(),
        columns=result_columns,
        noun="validation_results",
    )
    expected_runs.sort(key=lambda row: str(row[0]))
    expected_results.sort(key=lambda row: str(row[0]))
    if (
        len({str(row[0]) for row in actual_runs}) != len(actual_runs)
        or len({str(row[0]) for row in actual_results}) != len(actual_results)
        or actual_runs != expected_runs
        or actual_results != expected_results
    ):
        raise MigrationRequired("M42 exact validation table projection differs")

    runs_digest = _identity(
        {
            "schema": _M42_LEGACY_VALIDATION_PROJECTION_SCHEMA,
            "manifest_cid": _M42_LEGACY_PROJECTION_MANIFEST_CID,
            "event_watermark": _M42_LEGACY_PROJECTION_WATERMARK,
            "table": "validation_runs",
            "row_count": len(actual_runs),
            "rows": actual_runs,
        }
    )
    results_digest = _identity(
        {
            "schema": _M42_LEGACY_VALIDATION_PROJECTION_SCHEMA,
            "manifest_cid": _M42_LEGACY_PROJECTION_MANIFEST_CID,
            "event_watermark": _M42_LEGACY_PROJECTION_WATERMARK,
            "table": "validation_results",
            "row_count": len(actual_results),
            "rows": actual_results,
        }
    )
    if (
        runs_digest != _M42_LEGACY_VALIDATION_RUNS_DIGEST
        or results_digest != _M42_LEGACY_VALIDATION_RESULTS_DIGEST
    ):
        raise MigrationRequired("M42 validation table projection digest differs")
    return {
        "validation_run_count": len(actual_runs),
        "validation_result_count": len(actual_results),
        "validation_runs_digest": runs_digest,
        "validation_results_digest": results_digest,
        "legacy_validation_attempt_overlay_count": 1,
        "complete_validation_table_projection_verified": True,
    }


def _verify_m42_exact_legacy_projection(
    connection: Any,
    *,
    expected_target_evidence_row: tuple[Any, ...] | None = None,
    expected_successor_evidence_row: tuple[Any, ...] | None = None,
) -> dict[str, Any]:
    """Verify the closed legacy projection and, optionally, exact event 292.

    A caller-bound post-append row is singular and its CID, canonical body and
    immutable event envelope are reconstructed and rehashed here.  This helper
    establishes structural consistency, not target-body authority.  The
    production M42 verifier derives the expected row from the sealed migration
    body and independently repeats the row, event and prefix checks.
    """

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    projection = _m38_evidence_projection_from_events(
        connection, watermark=_M42_LEGACY_PROJECTION_WATERMARK
    )
    if (
        projection["evidence_node_count"] != _M42_LEGACY_EVIDENCE_NODE_COUNT
        or projection["evidence_event_count"]
        != _M42_LEGACY_EVIDENCE_EVENT_COUNT
        or projection["validation_event_count"]
        != _M42_LEGACY_VALIDATION_EVENT_COUNT
        or projection["passed_validation_event_count"]
        != _M42_LEGACY_PASSED_VALIDATION_EVENT_COUNT
        or projection["validation_evidence_node_count"]
        != _M42_LEGACY_VALIDATION_EVIDENCE_NODE_COUNT
    ):
        raise MigrationRequired("M42 legacy event-derived projection shape differs")
    prior_rows = _m42_apply_exact_legacy_evidence_overlay(
        projection["rows"], watermark=_M42_LEGACY_PROJECTION_WATERMARK
    )
    evidence_digest = _identity(
        {
            "schema": _M42_LEGACY_EVIDENCE_PROJECTION_SCHEMA,
            "manifest_cid": _M42_LEGACY_PROJECTION_MANIFEST_CID,
            "event_watermark": _M42_LEGACY_PROJECTION_WATERMARK,
            "evidence_node_count": len(prior_rows),
            "evidence_event_count": projection["evidence_event_count"],
            "validation_event_count": projection["validation_event_count"],
            "passed_validation_event_count": projection[
                "passed_validation_event_count"
            ],
            "validation_evidence_node_count": projection[
                "validation_evidence_node_count"
            ],
            "rows": prior_rows,
        }
    )
    if evidence_digest != _M42_LEGACY_EVIDENCE_PROJECTION_DIGEST:
        raise MigrationRequired("M42 legacy evidence projection digest differs")

    evidence_columns = (
        "evidence_id",
        "parent_evidence_id",
        "task_cid",
        "evidence_kind",
        "digest",
        "created_at",
        "body_json",
    )
    actual_rows = _m42_normalized_projection_rows(
        connection.execute(
            "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
            "created_at,body_json FROM evidence_nodes ORDER BY evidence_id"
        ).fetchall(),
        columns=evidence_columns,
        noun="legacy evidence projection",
    )
    normalized_target: list[tuple[Any, ...]] = []
    target_event_id = ""
    raw_target_event = connection.execute(
        "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
        "attempt_id,session_id,recorded_at,body_json FROM domain_events "
        "WHERE global_sequence=?",
        [_M42_TARGET_EVENT_WATERMARK],
    ).fetchone()
    if expected_target_evidence_row is None:
        if raw_target_event is not None:
            raise MigrationRequired("M42 target event exists without expected evidence")
    else:
        if not isinstance(expected_target_evidence_row, tuple):
            raise MigrationRequired("M42 target evidence row must be one tuple")
        normalized_target = _m42_normalized_projection_rows(
            [expected_target_evidence_row],
            columns=evidence_columns,
            noun="target evidence projection",
        )
        target_row = normalized_target[0]
        try:
            target_body = _m38_parse_json(target_row[6])
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise MigrationRequired("M42 target evidence body is invalid") from exc
        if (
            target_row[1] != ""
            or target_row[2] != _M42_OPERATOR_TASK_CID
            or target_row[3] != _M42_EVIDENCE_KIND
            or target_row[5] != _M42_CONTROL_RECORDED_AT
            or not all(isinstance(value, str) and value for value in target_row[2:6])
            or not isinstance(target_body, Mapping)
            or _canonical(target_body).decode("utf-8") != target_row[6]
            or content_identity(
                {
                    "task_cid": target_row[2],
                    "evidence_kind": target_row[3],
                    "digest": target_row[4],
                    "body": target_body,
                }
            )
            != target_row[0]
        ):
            raise MigrationRequired("M42 target evidence identity differs")
        if raw_target_event is None:
            raise MigrationRequired("M42 target evidence lacks event 292")
        event_columns = (
            "event_id",
            "stream_id",
            "sequence",
            "global_sequence",
            "event_type",
            "task_cid",
            "attempt_id",
            "session_id",
            "recorded_at",
            "body_json",
        )
        event_row = _m42_normalized_projection_rows(
            [raw_target_event],
            columns=event_columns,
            noun="target event projection",
        )[0]
        try:
            envelope = _m38_parse_json(event_row[9])
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise MigrationRequired("M42 target event body is invalid") from exc
        inner = envelope.get("body") if isinstance(envelope, Mapping) else None
        expected_inner = {
            "evidence_id": target_row[0],
            "parent_evidence_id": "",
            "task_cid": target_row[2],
            "evidence_kind": target_row[3],
            "digest": target_row[4],
            "body": target_body,
            "created_at": target_row[5],
            "revision": 0,
        }
        expected_envelope = {
            "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
            "event_type": "intent.evidence_recorded",
            "subject_id": target_row[0],
            "body": expected_inner,
            "recorded_at": target_row[5],
            "owner_id": "sawm-r2-m42-live-source-sealer",
        }
        target_event_id = content_identity(
            {
                "stream_id": "stream:intent",
                "sequence": _M42_TARGET_EVENT_WATERMARK,
                "global_sequence": _M42_TARGET_EVENT_WATERMARK,
                "event_type": "intent.evidence_recorded",
                "body": expected_envelope,
            }
        )
        if (
            event_row[0] != target_event_id
            or event_row[1] != "stream:intent"
            or int(event_row[2]) != _M42_TARGET_EVENT_WATERMARK
            or int(event_row[3]) != _M42_TARGET_EVENT_WATERMARK
            or event_row[4] != "intent.evidence_recorded"
            or event_row[5] != target_row[2]
            or event_row[6] != ""
            or event_row[7] != "session:intent"
            or event_row[8] != target_row[5]
            or envelope != expected_envelope
            or inner != expected_inner
        ):
            raise MigrationRequired("M42 target event/evidence binding differs")
    normalized_successor: list[tuple[Any, ...]] = []
    if expected_successor_evidence_row is not None:
        if not isinstance(expected_successor_evidence_row, tuple):
            raise MigrationRequired(
                "M42 successor evidence row must be one tuple"
            )
        normalized_successor = _m42_normalized_projection_rows(
            [expected_successor_evidence_row],
            columns=evidence_columns,
            noun="successor evidence projection",
        )
        successor_row = normalized_successor[0]
        try:
            successor_body = _m38_parse_json(successor_row[6])
        except (TypeError, ValueError, json.JSONDecodeError) as exc:
            raise MigrationRequired(
                "M42 successor evidence body is invalid"
            ) from exc
        if (
            successor_row[1] != ""
            or not all(
                isinstance(value, str) and value
                for value in successor_row[2:6]
            )
            or not isinstance(successor_body, Mapping)
            or _canonical(successor_body).decode("utf-8") != successor_row[6]
            or content_identity(
                {
                    "task_cid": successor_row[2],
                    "evidence_kind": successor_row[3],
                    "digest": successor_row[4],
                    "body": successor_body,
                }
            )
            != successor_row[0]
        ):
            raise MigrationRequired("M42 successor evidence identity differs")

    expected_by_id = {str(row[0]): row for row in prior_rows}
    if len(expected_by_id) != len(prior_rows):
        raise MaterializationError("M42 transformed evidence identities duplicate")
    for row in normalized_target:
        evidence_id = str(row[0])
        if evidence_id in expected_by_id:
            raise MigrationRequired("M42 additional evidence identity collides")
        expected_by_id[evidence_id] = row
    exact_physical_by_id = dict(expected_by_id)
    for row in normalized_successor:
        evidence_id = str(row[0])
        if evidence_id in exact_physical_by_id:
            raise MigrationRequired("M42 successor evidence identity collides")
        exact_physical_by_id[evidence_id] = row
    actual_by_id = {str(row[0]): row for row in actual_rows}
    if len(actual_by_id) != len(actual_rows):
        raise MigrationRequired("M42 actual evidence identities duplicate")
    if set(actual_by_id) != set(exact_physical_by_id):
        raise MigrationRequired("M42 exact evidence projection membership differs")
    if actual_by_id != exact_physical_by_id:
        raise MigrationRequired("M42 exact evidence projection rows differ")

    validation = _m42_legacy_validation_table_projection(connection)
    return {
        "legacy_event_watermark": _M42_LEGACY_PROJECTION_WATERMARK,
        "prior_evidence_node_count": len(prior_rows),
        "total_evidence_node_count": len(expected_by_id),
        "evidence_event_count": projection["evidence_event_count"],
        "validation_event_count": projection["validation_event_count"],
        "passed_validation_event_count": projection[
            "passed_validation_event_count"
        ],
        "validation_evidence_node_count": projection[
            "validation_evidence_node_count"
        ],
        "legacy_evidence_refresh_overlay_count": len(
            _M42_LEGACY_EVIDENCE_REFRESH_ROWS
        ),
        "legacy_compact_validation_evidence_overlay_count": 1,
        "additional_evidence_node_count": len(normalized_target),
        "target_evidence_node_count": len(normalized_target),
        "target_event_id": target_event_id or None,
        "legacy_projection_manifest_cid": _M42_LEGACY_PROJECTION_MANIFEST_CID,
        "legacy_evidence_projection_digest": evidence_digest,
        "exact_legacy_evidence_overlay_verified": True,
        **validation,
    }


def _m39_expected_historical_m38_rows(
    config: Mapping[str, Any],
) -> tuple[dict[str, Any], tuple[Any, ...], tuple[Any, ...]]:
    """Reconstruct the closed event-291 rows from its historical authority."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    body = _m39_historical_m38_body(config)
    event_body = {
        "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
        "event_type": "intent.evidence_recorded",
        "subject_id": _M39_M38_EVIDENCE_ID,
        "body": {
            "evidence_id": _M39_M38_EVIDENCE_ID,
            "parent_evidence_id": "",
            "task_cid": _M39_OPERATOR_TASK_CID,
            "evidence_kind": _M39_M38_EVIDENCE_KIND,
            "digest": _M39_M38_EVIDENCE_DIGEST,
            "body": body,
            "created_at": _M39_M38_RECORDED_AT,
            "revision": 0,
        },
        "recorded_at": _M39_M38_RECORDED_AT,
        "owner_id": "sawm-r2-m38-live-source-sealer",
    }
    evidence_id = content_identity(
        {
            "task_cid": _M39_OPERATOR_TASK_CID,
            "evidence_kind": _M39_M38_EVIDENCE_KIND,
            "digest": _M39_M38_EVIDENCE_DIGEST,
            "body": body,
        }
    )
    event_id = content_identity(
        {
            "stream_id": "stream:intent",
            "sequence": _M39_PRIOR_EVENT_WATERMARK,
            "global_sequence": _M39_PRIOR_EVENT_WATERMARK,
            "event_type": "intent.evidence_recorded",
            "body": event_body,
        }
    )
    if evidence_id != _M39_M38_EVIDENCE_ID or event_id != _M39_M38_EVENT_ID:
        raise MaterializationError("M39 historical M38 event identities differ")
    evidence_row = (
        evidence_id,
        "",
        _M39_OPERATOR_TASK_CID,
        _M39_M38_EVIDENCE_KIND,
        _M39_M38_EVIDENCE_DIGEST,
        _M39_M38_RECORDED_AT,
        _canonical(body).decode("utf-8"),
    )
    event_row = (
        event_id,
        "stream:intent",
        _M39_PRIOR_EVENT_WATERMARK,
        _M39_PRIOR_EVENT_WATERMARK,
        "intent.evidence_recorded",
        _M39_OPERATOR_TASK_CID,
        "",
        "session:intent",
        _M39_M38_RECORDED_AT,
        _canonical(event_body).decode("utf-8"),
    )
    return body, evidence_row, event_row


def _verify_m39_committed_m38_event(
    connection: Any,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Verify all identity-bearing fields of committed M38 event 291."""

    body, expected_evidence, expected_event = _m39_expected_historical_m38_rows(
        config
    )
    evidence = connection.execute(
        "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
        "created_at,body_json FROM evidence_nodes WHERE evidence_id=?",
        [_M39_M38_EVIDENCE_ID],
    ).fetchone()
    event = connection.execute(
        "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
        "attempt_id,session_id,recorded_at,body_json FROM domain_events "
        "WHERE global_sequence=?",
        [_M39_PRIOR_EVENT_WATERMARK],
    ).fetchone()
    if not _m39_exact_row_matches(
        evidence,
        (
            "evidence_id",
            "parent_evidence_id",
            "task_cid",
            "evidence_kind",
            "digest",
            "created_at",
            "body_json",
        ),
        expected_evidence,
    ) or not _m39_exact_row_matches(
        event,
        (
            "event_id",
            "stream_id",
            "sequence",
            "global_sequence",
            "event_type",
            "task_cid",
            "attempt_id",
            "session_id",
            "recorded_at",
            "body_json",
        ),
        expected_event,
    ):
        raise MigrationRequired("M39 committed M38 event/evidence rows differ")
    projection = _m38_evidence_projection_from_events(
        connection, watermark=_M39_PRIOR_EVENT_WATERMARK
    )
    if (
        projection["evidence_node_count"] != _M39_PRIOR_EVIDENCE_NODE_COUNT
        or projection["evidence_event_count"] != _M39_PRIOR_EVIDENCE_EVENT_COUNT
        or projection["validation_event_count"]
        != _M39_PRIOR_VALIDATION_EVENT_COUNT
        or projection["passed_validation_event_count"]
        != _M39_PRIOR_PASSED_VALIDATION_EVENT_COUNT
        or projection["validation_evidence_node_count"]
        != _M39_PRIOR_VALIDATION_EVENT_COUNT
    ):
        raise MigrationRequired("M39 committed M38 evidence projection differs")
    return {
        "historical_m38_body": body,
        "prior_m38_event_id": _M39_M38_EVENT_ID,
        "prior_m38_evidence_id": _M39_M38_EVIDENCE_ID,
        "committed_m38_event_id": _M39_M38_EVENT_ID,
        "committed_m38_evidence_id": _M39_M38_EVIDENCE_ID,
        "prior_evidence_node_count": projection["evidence_node_count"],
        "prior_evidence_event_count": projection["evidence_event_count"],
        "prior_validation_event_count": projection["validation_event_count"],
        "prior_passed_validation_event_count": projection[
            "passed_validation_event_count"
        ],
        "committed_m38_event_and_evidence_verified": True,
    }


def _m39_expected_event_body(
    body: Mapping[str, Any],
    *,
    evidence_id: str,
    digest: str,
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    target = authority["target_authority"]
    inner = {
        "evidence_id": evidence_id,
        "parent_evidence_id": "",
        "task_cid": target["operator_task_cid"],
        "evidence_kind": target["evidence_kind"],
        "digest": digest,
        "body": dict(body),
        "created_at": _M39_CONTROL_RECORDED_AT,
        "revision": 0,
    }
    return {
        "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
        "event_type": "intent.evidence_recorded",
        "subject_id": evidence_id,
        "body": inner,
        "recorded_at": _M39_CONTROL_RECORDED_AT,
        "owner_id": "sawm-r2-m39-live-source-sealer",
    }


def _inspect_m39_live_projection(
    source: Any,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    expected_event_watermark: int,
    expected_projection_cid: str,
) -> dict[str, Any]:
    return _inspect_m37_live_projection(
        source,
        population,
        authority,
        expected_event_watermark=expected_event_watermark,
        expected_projection_cid=expected_projection_cid,
    )


def _inspect_m39_generation_restart_rows(
    source: Any,
    identity: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Verify generation 29/30 through M39's sealed historical authority."""

    historical = authority.get("historical_m38_authority")
    if (
        not isinstance(historical, Mapping)
        or _identity(historical) != _M39_M38_AUTHORITY_CID
        or not isinstance(historical.get("stopped_owner"), Mapping)
    ):
        raise MigrationRequired(
            "M39 historical M38 generation-restart authority differs"
        )
    return _inspect_m37_generation_restart_rows(source, identity, historical)


def _verify_m39_live_materialization(
    source: Any,
    identity: Mapping[str, Any],
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    authority: Mapping[str, Any],
    validation_digest: str,
    *,
    repository_root: Path | None = None,
) -> dict[str, Any]:
    """Verify immutable event 291 plus M39's sole event 292 and live owner."""

    verification_root = (
        REPO_ROOT if repository_root is None else Path(repository_root).resolve()
    )
    control, coordination = _m39_target_paths(
        verification_root, config, authority
    )
    preserved = _verify_m37_preserved_receipts(
        verification_root, control, coordination
    )
    for revision in ("m37", "m38"):
        if os.path.lexists(
            control.parent / f"{revision}-source-successor-receipt.json"
        ):
            raise MigrationRequired(
                f"M39 superseded {revision.upper()} receipt unexpectedly exists"
            )
    body = _m39_migration_body(population, config, validation_digest)
    digest = _identity(body)
    target = authority["target_authority"]
    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    evidence_id = content_identity(
        {
            "task_cid": target["operator_task_cid"],
            "evidence_kind": target["evidence_kind"],
            "digest": digest,
            "body": body,
        }
    )
    event_body = _m39_expected_event_body(
        body, evidence_id=evidence_id, digest=digest, authority=authority
    )
    expected_event_id = content_identity(
        {
            "stream_id": "stream:intent",
            "sequence": _M39_TARGET_EVENT_WATERMARK,
            "global_sequence": _M39_TARGET_EVENT_WATERMARK,
            "event_type": "intent.evidence_recorded",
            "body": event_body,
        }
    )
    head = _inspect_m39_live_projection(
        source,
        population,
        authority,
        expected_event_watermark=_M39_TARGET_EVENT_WATERMARK,
        expected_projection_cid=_M39_TARGET_PROJECTION_CID,
    )
    if (
        _m38_projection_cid_at_watermark(source, _M39_PRIOR_EVENT_WATERMARK)
        != _M39_PRIOR_PROJECTION_CID
        or _m38_projection_cid_at_watermark(source, _M39_TARGET_EVENT_WATERMARK)
        != _M39_TARGET_PROJECTION_CID
    ):
        raise MigrationRequired("M39 prior/target projection derivation differs")
    restart = _inspect_m39_generation_restart_rows(source, identity, authority)
    if (
        restart.get("live_server_id") != _M39_LIVE_SERVER_ID
        or restart.get("live_process_birth_id") != _M39_LIVE_PROCESS_BIRTH_ID
        or restart.get("live_started_at") != _M39_LIVE_STARTED_AT
        or identity.get("server_id") != _M39_LIVE_SERVER_ID
        or identity.get("process_birth_id") != _M39_LIVE_PROCESS_BIRTH_ID
        or identity.get("started_at") != _M39_LIVE_STARTED_AT
    ):
        raise MigrationRequired("M39 exact live generation-30 owner differs")
    with source.intent._connection(write=False) as connection:
        prior = _verify_m39_committed_m38_event(connection, config)
        evidence = connection.execute(
            "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
            "created_at,body_json FROM evidence_nodes WHERE evidence_id=?",
            [evidence_id],
        ).fetchone()
        event = connection.execute(
            "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
            "attempt_id,session_id,recorded_at,body_json FROM domain_events "
            "WHERE global_sequence=?",
            [_M39_TARGET_EVENT_WATERMARK],
        ).fetchone()
        prior_prefix = _event_prefix_digest(
            connection, _M39_PRIOR_EVENT_WATERMARK
        )
        prefix = _event_prefix_digest(connection, _M39_TARGET_EVENT_WATERMARK)
        evidence_projection = _verify_m38_evidence_projection(
            connection, watermark=_M39_TARGET_EVENT_WATERMARK
        )
        semantic = _semantic_authority_digest_on(connection)
    expected_evidence = (
        evidence_id,
        "",
        target["operator_task_cid"],
        target["evidence_kind"],
        digest,
        _M39_CONTROL_RECORDED_AT,
        _canonical(body).decode("utf-8"),
    )
    expected_event = (
        expected_event_id,
        "stream:intent",
        _M39_TARGET_EVENT_WATERMARK,
        _M39_TARGET_EVENT_WATERMARK,
        "intent.evidence_recorded",
        target["operator_task_cid"],
        "",
        "session:intent",
        _M39_CONTROL_RECORDED_AT,
        _canonical(event_body).decode("utf-8"),
    )
    if (
        not _m39_exact_row_matches(
            evidence,
            (
                "evidence_id",
                "parent_evidence_id",
                "task_cid",
                "evidence_kind",
                "digest",
                "created_at",
                "body_json",
            ),
            expected_evidence,
        )
        or not _m39_exact_row_matches(
            event,
            (
                "event_id",
                "stream_id",
                "sequence",
                "global_sequence",
                "event_type",
                "task_cid",
                "attempt_id",
                "session_id",
                "recorded_at",
                "body_json",
            ),
            expected_event,
        )
        or prior_prefix
        != (_M39_PRIOR_EVENT_PREFIX_SHA256, _M39_PRIOR_EVENT_WATERMARK)
        or prefix[1] != _M39_TARGET_EVENT_WATERMARK
        or semantic != _M39_SEMANTIC_AUTHORITY_DIGEST
        or evidence_projection["evidence_node_count"]
        != _M39_TARGET_EVIDENCE_NODE_COUNT
        or evidence_projection["evidence_event_count"]
        != _M39_TARGET_EVIDENCE_EVENT_COUNT
        or evidence_projection["validation_event_count"]
        != _M39_TARGET_VALIDATION_EVENT_COUNT
        or evidence_projection["passed_validation_event_count"]
        != _M39_TARGET_PASSED_VALIDATION_EVENT_COUNT
        or evidence_projection["validation_evidence_node_count"]
        != _M39_TARGET_VALIDATION_EVENT_COUNT
        or evidence_projection["evidence_node_count"]
        != prior["prior_evidence_node_count"] + 1
        or evidence_projection["evidence_event_count"]
        != prior["prior_evidence_event_count"] + 1
        or evidence_projection["validation_event_count"]
        != prior["prior_validation_event_count"]
        or evidence_projection["passed_validation_event_count"]
        != prior["prior_passed_validation_event_count"]
    ):
        raise MigrationRequired("M39 exact target event/evidence authority differs")
    return {
        **head,
        **restart,
        **{key: value for key, value in prior.items() if key != "historical_m38_body"},
        "migration_digest": digest,
        "migration_evidence_id": evidence_id,
        "migration_evidence_event_id": expected_event_id,
        "target_event_prefix_sha256": prefix[0],
        "prior_event_prefix_verified": True,
        "prior_projection_recomputed": True,
        "target_projection_recomputed": True,
        "m37_receipt_absence_verified": True,
        "m38_receipt_absence_verified": True,
        "m38_receipt_created_or_rewritten": False,
        "same_live_generation_30_owner": True,
        "m36_historical_anchor_verified": preserved[
            "m36_historical_anchor_verified"
        ],
        "stale_owner_recovery_receipt_verified": preserved[
            "stale_owner_recovery_receipt_verified"
        ],
        **evidence_projection,
        "semantic_authority_digest": semantic,
        "full_event_and_evidence_body_verified": True,
        "queried_and_mutated_through_live_quack_only": True,
        "direct_authoritative_file_opened": False,
        "plan_revision_changes": 0,
        "goal_revision_changes": 0,
        "evidence_node_changes": 1,
        "evidence_event_changes": 1,
        "validation_event_changes": 0,
        "task_revision_changes": 0,
        "task_status_changes": 0,
        "coordination_semantic_changes": 0,
        "accepted_completion_changes": 0,
        "worker_self_approval": False,
    }


