def _m48_authority_reference() -> dict[str, Any]:
    """Return M48's reference and reject a sealed-body drift."""

    authority = _expected_m48_post_m47_clean_shutdown_restart_successor_authority()
    if not _M48_AUTHORITY_CID.endswith(
        "PENDING_M48_FINAL_CONTROL_AUTHORITY_CID"
    ) and _identity(authority) != _M48_AUTHORITY_CID:
        raise MaterializationError("M48 source successor authority CID differs")
    return {
        "schema": "sawm/operator-control-authority-reference@1",
        "migration_revision": _M48_MIGRATION_REVISION,
        "authority_cid": _M48_AUTHORITY_CID,
    }


def _validated_m48_live_preflight_contract(
    authority: Mapping[str, Any],
) -> Mapping[str, Any]:
    """Validate M48's closed generation-34 to generation-35 contract."""

    expected = _expected_m48_post_m47_clean_shutdown_restart_successor_authority()
    contract = authority.get("live_preflight_contract")
    receipt = authority.get("preserved_m47_receipt")
    materialization = authority.get("preserved_m47_materialization")
    shutdown = authority.get("failed_test_induced_shutdown_observation")
    chain = authority.get("source_chain")
    if (
        dict(authority) != expected
        or not all(
            isinstance(value, Mapping)
            for value in (contract, receipt, materialization, shutdown, chain)
        )
        or authority.get("schema")
        != "sawm/post-m47-clean-shutdown-restart-authorization@1"
        or authority.get("authorized") is not True
        or authority.get("authority") != "operator_control_plane"
        or authority.get("migration_revision") != _M48_MIGRATION_REVISION
        or authority.get("migration_kind") != _M48_SUPERSESSION_REASON
        or authority.get("target_generation") != _M48_TARGET_GENERATION
        or authority.get("target_event_watermark") != _M48_TARGET_EVENT_WATERMARK
        or contract.get("prior_generation") != _M48_PRIOR_GENERATION
        or contract.get("target_generation") != _M48_TARGET_GENERATION
        or contract.get("prior_event_watermark") != _M48_PRIOR_EVENT_WATERMARK
        or contract.get("target_event_watermark") != _M48_TARGET_EVENT_WATERMARK
        or contract.get("m47_receipt_must_be_preserved") is not True
        or contract.get("m44_receipt_must_remain_absent") is not True
        or contract.get("event_304_must_be_preserved") is not True
        or contract.get("event_305_must_be_absent_before_append") is not True
        or contract.get("generation_restart_authorized") is not True
        or receipt.get("receipt_cid") != _M48_M47_RECEIPT_CID
        or receipt.get("created_or_rewritten") is not False
        or materialization.get("authority_cid") != _M48_M47_AUTHORITY_CID
        or materialization.get("event_id") != _M48_M47_EVENT_ID
        or materialization.get("evidence_id") != _M48_M47_EVIDENCE_ID
        or materialization.get("migration_digest") != _M48_M47_MIGRATION_DIGEST
        or materialization.get("m44_receipt_absent") is not True
        or shutdown.get("m47_materialization_was_valid") is not True
        or shutdown.get("test_suite_completed") is not False
        or shutdown.get("test_suite_exit_code") != 2
        or shutdown.get("passed_tests_before_interruption") != 21
        or shutdown.get("interruption_kind") != "KeyboardInterrupt"
        or shutdown.get("owner_shutdown_was_clean") is not True
        or shutdown.get("operational_history_only") is not True
        or shutdown.get("validation_authority") is not False
        or shutdown.get("task_completion_authority") is not False
        or shutdown.get("coordination_authority") is not False
        or shutdown.get("worker_self_approval") is not False
        or chain.get("final_control_parent") != _M48_M47_FINAL_CONTROL_COMMIT
        or chain.get("ordinary_repair_commit_count") != 0
        or chain.get("final_control_commit_count") != 1
        or chain.get("current_commit_identity_embedded_in_authority") is not False
        or authority.get("operator_control_paths")
        != sorted(_M48_OPERATOR_CONTROL_PATHS)
        or authority.get("exact_changes", {}).get("event_suffix_length") != 1
        or authority.get("exact_changes", {}).get("task_revision_changes") != 0
        or authority.get("exact_changes", {}).get("task_status_changes") != 0
        or authority.get("exact_changes", {}).get("accepted_completion_changes")
        != 0
        or authority.get("preservation", {}).get("m47_receipt_preserved_exactly")
        is not True
        or authority.get("preservation", {}).get("m44_receipt_remains_absent")
        is not True
        or authority.get("preservation", {}).get("worker_self_approval")
        is not False
    ):
        raise MaterializationError("M48 live preflight contract differs")
    return contract


def _m48_successor_configured(config: Mapping[str, Any]) -> bool:
    key = _M48_SUPERSESSION_REASON
    if key not in config:
        return False
    if config.get(key) != _m48_authority_reference():
        raise MaterializationError("M48 successor authority reference differs")
    return True


def _m48_successor_configured_on_any_surface(
    root: Path, config: Mapping[str, Any]
) -> bool:
    key = _M48_SUPERSESSION_REASON
    migration = _load_json(
        root
        / "docs/architecture/semantic_addressed_world_model_inventory/"
        "prior_materialization_migration.json"
    )
    seal = _load_json(
        root / "config/semantic_addressed_world_model_dependencies.seal.json"
    )
    presence = (key in config, key in migration, f"{key}_cid" in seal)
    if any(presence) and not all(presence):
        raise MaterializationError("M48 successor authority is only partially declared")
    if not any(presence):
        return False
    reference = _m48_authority_reference()
    if (
        config.get(key) != reference
        or migration.get(key) != reference
        or seal.get(f"{key}_cid") != reference["authority_cid"]
    ):
        raise MaterializationError("M48 successor authority differs across controls")
    return _m48_successor_configured(config)


def _assert_m48_historical_m47_controls(
    scheduler: Mapping[str, Any],
    migration: Mapping[str, Any],
    seal: Mapping[str, Any],
) -> None:
    """Preserve M47 exactly without re-entering its current-HEAD gate."""

    _assert_m47_historical_m46_controls(scheduler, migration, seal)
    key = _M47_SUPERSESSION_REASON
    reference = _m47_authority_reference()
    body = (
        _expected_m47_ignored_python_cache_preservation_and_recovery_successor_authority()
    )
    if (
        scheduler.get(key) != reference
        or migration.get(key) != reference
        or seal.get(f"{key}_cid") != reference["authority_cid"]
        or reference.get("authority_cid") != _M48_M47_AUTHORITY_CID
        or _identity(body) != _M48_M47_AUTHORITY_CID
        or len(_canonical(body)) != _M48_M47_AUTHORITY_SIZE
    ):
        raise MaterializationError("M48 historical M47 authority differs")


def _m48_source_binding_authority(
    root: Path,
    population: Mapping[str, Any],
    config: Mapping[str, Any],
) -> dict[str, Any]:
    expected = _expected_m48_post_m47_clean_shutdown_restart_successor_authority()
    reference = _m48_authority_reference()
    key = _M48_SUPERSESSION_REASON
    inventory = population.get("migration_inventory", {})
    seal = _load_json(
        root / "config/semantic_addressed_world_model_dependencies.seal.json"
    )
    if not isinstance(inventory, Mapping):
        raise MaterializationError("M48 migration inventory is invalid")
    _assert_m48_historical_m47_controls(config, inventory, seal)
    if (
        config.get(key) != reference
        or inventory.get(key) != reference
        or seal.get(f"{key}_cid") != reference["authority_cid"]
    ):
        raise MaterializationError("M48 authority differs across protected controls")
    _validated_m48_live_preflight_contract(expected)
    return expected


def _assert_m48_source_delta(
    root: Path,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> None:
    """Require exactly one direct nine-control child of M47."""

    identities = (
        _M48_M47_FINAL_CONTROL_COMMIT,
        _M48_M47_FINAL_CONTROL_PARENT,
        _M48_M47_FINAL_CONTROL_TREE,
        *tuple(_M48_M47_FINAL_CONTROL_BLOBS.values()),
    )
    if (
        any(re.fullmatch(r"[0-9a-f]{40}", value) is None for value in identities)
        or _M48_AUTHORITY_CID.endswith("PENDING_M48_FINAL_CONTROL_AUTHORITY_CID")
    ):
        raise MaterializationError("M48 final control identities are not resealed")
    current = str(population["source_binding"]["head"])
    chain = authority.get("source_chain")
    controls = set(authority.get("operator_control_paths") or ())
    base_parents = _git(
        root, "rev-list", "--parents", "-n", "1", _M48_M47_FINAL_CONTROL_COMMIT
    ).split()
    current_parents = _git(root, "rev-list", "--parents", "-n", "1", current).split()
    if (
        current == _M48_M47_FINAL_CONTROL_COMMIT
        or not isinstance(chain, Mapping)
        or controls != set(_M48_OPERATOR_CONTROL_PATHS)
        or _M48_OPERATOR_CONTROL_PATHS != _M47_OPERATOR_CONTROL_PATHS
        or chain.get("m47_final_control_commit")
        != _M48_M47_FINAL_CONTROL_COMMIT
        or chain.get("m47_final_control_parent")
        != _M48_M47_FINAL_CONTROL_PARENT
        or chain.get("m47_final_control_tree") != _M48_M47_FINAL_CONTROL_TREE
        or chain.get("m47_final_control_blobs")
        != dict(_M48_M47_FINAL_CONTROL_BLOBS)
        or chain.get("m47_final_control_modes")
        != dict(_M48_M47_FINAL_CONTROL_MODES)
        or chain.get("final_control_parent") != _M48_M47_FINAL_CONTROL_COMMIT
        or int(chain.get("ordinary_repair_commit_count", -1)) != 0
        or int(chain.get("final_control_commit_count") or 0) != 1
        or chain.get("current_commit_identity_embedded_in_authority") is not False
        or base_parents
        != [_M48_M47_FINAL_CONTROL_COMMIT, _M48_M47_FINAL_CONTROL_PARENT]
        or current_parents != [current, _M48_M47_FINAL_CONTROL_COMMIT]
        or _git(root, "rev-parse", f"{_M48_M47_FINAL_CONTROL_COMMIT}^{{tree}}")
        != _M48_M47_FINAL_CONTROL_TREE
        or _m27_name_status(root, _M48_M47_FINAL_CONTROL_COMMIT, current)
        != {path: "M" for path in controls}
        or population["source_binding"].get("tree")
        != _git(root, "rev-parse", f"{current}^{{tree}}")
        or int(authority.get("ordinary_source_changes", -1)) != 0
    ):
        raise MaterializationError("M48 exact source-only control chain differs")
    for path, oid in _M48_M47_FINAL_CONTROL_BLOBS.items():
        if _git(
            root, "rev-parse", f"{_M48_M47_FINAL_CONTROL_COMMIT}:{path}"
        ) != oid:
            raise MaterializationError(f"M48 M47-final-control blob differs: {path}")
        if (
            _git(root, "ls-tree", _M48_M47_FINAL_CONTROL_COMMIT, "--", path)
            != f"{_M48_M47_FINAL_CONTROL_MODES[path]} blob {oid}\t{path}"
        ):
            raise MaterializationError(f"M48 M47-final-control mode differs: {path}")
    _assert_m43_current_control_modes(root, current, controls)
    for dependency, gitlink_key, tree_key, population_key in (
        (
            "ipfs_datasets_py",
            "current_datasets_gitlink",
            "current_datasets_tree",
            "datasets_gitlink",
        ),
        ("ipfs_kit_py", "current_kit_gitlink", "current_kit_tree", "kit_gitlink"),
    ):
        gitlink = str(authority[gitlink_key])
        if (
            any(
                _git(root, "rev-parse", f"{head}:{dependency}") != gitlink
                for head in (_M48_M47_FINAL_CONTROL_COMMIT, current)
            )
            or population["source_binding"].get(population_key) != gitlink
            or _git(root / dependency, "rev-parse", f"{gitlink}^{{tree}}")
            != authority[tree_key]
        ):
            raise MaterializationError(f"M48 {dependency} authority differs")

def _m48_target_paths(
    root: Path,
    config: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[Path, Path]:
    runtime = authority["runtime_binding"]
    program = config.get("database_program")
    owner = config.get("quack_owner")
    expected_runtime_paths = {
        "root": _M48_RUNTIME_ROOT,
        "state": f"{_M48_RUNTIME_ROOT}/state",
        "worktrees": _M48_WORKTREE_ROOT,
        "merge_queue": f"{_M48_RUNTIME_ROOT}/merge-queue",
        "logs": f"{_M48_RUNTIME_ROOT}/logs",
        "generated_runtime_artifacts_are_completion_authority": False,
    }
    if (
        not isinstance(program, Mapping)
        or not isinstance(owner, Mapping)
        or program.get("store_id") != _M48_STORE_ID
        or program.get("store_generation") != str(_M48_TARGET_GENERATION)
        or program.get("quack_endpoint") != runtime["quack_endpoint"]
        or program.get("worktree_root") != _M48_WORKTREE_ROOT
        or owner.get("database_path") != _M48_STORE_ID
        or owner.get("store_id") != _M48_STORE_ID
        or owner.get("port") != _M48_TARGET_QUACK_PORT
        or owner.get("state_dir") != f"{_M48_RUNTIME_ROOT}/quack-owner"
        or config.get("runtime_paths") != expected_runtime_paths
    ):
        raise MaterializationError("scheduler M48 runtime binding differs")
    control = (root / _M48_STORE_ID).resolve()
    coordination = (root / _M48_COORDINATION_STORE_ID).resolve()
    if not control.is_relative_to(root) or not coordination.is_relative_to(root):
        raise MaterializationError("M48 runtime path escapes repository")
    return control, coordination


def _m48_migration_body(
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    validation_digest: str,
) -> dict[str, Any]:
    authority = _expected_m48_post_m47_clean_shutdown_restart_successor_authority()
    return {
        "schema": "sawm/post-m47-clean-shutdown-restart-source-seal@1",
        "authority": "operator_control_plane",
        "migration_revision": _M48_MIGRATION_REVISION,
        "migration_kind": _M48_SUPERSESSION_REASON,
        "supersession_mode": _M48_SUPERSESSION_MODE,
        "program_definition_cid": population["program_definition_cid"],
        "current_source_binding_cid": population["source_binding"][
            "source_binding_cid"
        ],
        "current_source_head": population["source_binding"]["head"],
        "current_source_tree": population["source_binding"]["tree"],
        "validation_digest": validation_digest,
        "authorization_cid": _identity(authority),
        "runtime_binding": authority["runtime_binding"],
        "prior_authority": authority["prior_authority"],
        "stopped_owner": authority["stopped_owner"],
        "preserved_m47_receipt": authority["preserved_m47_receipt"],
        "preserved_m47_materialization": authority[
            "preserved_m47_materialization"
        ],
        "failed_test_induced_shutdown_observation": authority[
            "failed_test_induced_shutdown_observation"
        ],
        "live_preflight_contract": authority["live_preflight_contract"],
        "target_authority": authority["target_authority"],
        "source_chain": authority["source_chain"],
        "exact_changes": authority["exact_changes"],
        "preservation": authority["preservation"],
        "authenticated_mutation_route": {
            "transport": "quack_proxy_only",
            "endpoint_from_live_owner_discovery": True,
            "token_from_secret_handoff_or_environment_only": True,
            "token_in_argv": False,
            "token_in_evidence": False,
            "direct_authoritative_file_opened": False,
        },
        "scheduler_runtime_root": config["runtime_paths"]["root"],
        "accepted_completion_changes": 0,
        "worker_self_approval": False,
    }


def _verify_m48_preserved_m47_receipt(
    root: Path, control: Path
) -> dict[str, Any]:
    """Re-hash the immutable M47 source-seal marker independently."""

    # M47 delegates to M46 as immutable history.  Revalidate that predecessor
    # first so preserving only the outer M47 bytes cannot hide inner-chain
    # drift.
    _verify_m47_preserved_m46_receipt(root, control)
    path = control.parent / "m47-source-successor-receipt.json"
    observed, observed_sha = _load_nofollow_json(
        path, root=root, noun="M48 preserved M47 source successor receipt"
    )
    try:
        receipt_stat = path.stat(follow_symlinks=False)
    except OSError as exc:
        raise MigrationRequired("M48 preserved M47 receipt is unavailable") from exc
    unhashed = dict(observed)
    claimed = str(unhashed.pop("receipt_cid", ""))
    if (
        observed_sha != _M48_M47_RECEIPT_SHA256
        or int(receipt_stat.st_size) != _M48_M47_RECEIPT_SIZE
        or stat.S_IMODE(receipt_stat.st_mode) != 0o600
        or claimed != _M48_M47_RECEIPT_CID
        or claimed != _identity(unhashed)
        or observed.get("migration_revision") != _M47_MIGRATION_REVISION
        or observed.get(f"{_M47_SUPERSESSION_REASON}_cid")
        != _M48_M47_AUTHORITY_CID
        or observed.get("current_source_binding_cid")
        != _M48_M47_SOURCE_BINDING_CID
        or observed.get("target_generation") != _M48_PRIOR_GENERATION
        or observed.get("target_event_watermark") != _M48_PRIOR_EVENT_WATERMARK
        or observed.get("migration_digest") != _M48_M47_MIGRATION_DIGEST
        or observed.get("migration_evidence_event_id") != _M48_M47_EVENT_ID
        or observed.get("migration_evidence_id") != _M48_M47_EVIDENCE_ID
        or observed.get("target_event_prefix_sha256")
        != _M48_PRIOR_EVENT_PREFIX_SHA256
        or observed.get("projection_cid") != _M48_PRIOR_PROJECTION_CID
        or observed.get("m44_receipt_absent") is not True
        or observed.get("control_database_is_authority") is not True
        or observed.get("authoritative") is not False
        or observed.get("worker_self_approval") is not False
    ):
        raise MigrationRequired("M48 preserved M47 receipt differs")
    return observed


def _verify_m48_preserved_m47_materialization(
    connection: Any,
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    """Re-hash M47's delegated event-304/evidence rows."""

    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    evidence = connection.execute(
        "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
        "created_at,body_json FROM evidence_nodes WHERE evidence_id=?",
        [_M48_M47_EVIDENCE_ID],
    ).fetchone()
    event = connection.execute(
        "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
        "attempt_id,session_id,recorded_at,body_json FROM domain_events "
        "WHERE global_sequence=?",
        [_M48_PRIOR_EVENT_WATERMARK],
    ).fetchone()
    if evidence is None or event is None:
        raise MigrationRequired("M48 preserved M47 event/evidence is missing")
    normalized_evidence = _positional_rows([evidence], 7)[0]
    normalized_event = _positional_rows([event], 10)[0]
    body = _m38_parse_json(normalized_evidence[6])
    envelope = _m38_parse_json(normalized_event[9])
    digest = str(receipt.get("migration_digest") or "")
    expected_inner = {
        "evidence_id": _M48_M47_EVIDENCE_ID,
        "parent_evidence_id": "",
        "task_cid": _M42_OPERATOR_TASK_CID,
        "evidence_kind": _M47_EVIDENCE_KIND,
        "digest": digest,
        "body": body,
        "created_at": _M47_CONTROL_RECORDED_AT,
        "revision": 0,
    }
    expected_envelope = {
        "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
        "event_type": "intent.evidence_recorded",
        "subject_id": _M48_M47_EVIDENCE_ID,
        "body": expected_inner,
        "recorded_at": _M47_CONTROL_RECORDED_AT,
        "owner_id": "sawm-r2-m47-live-source-sealer",
    }
    rehashed_evidence_id = content_identity(
        {
            "task_cid": _M42_OPERATOR_TASK_CID,
            "evidence_kind": _M47_EVIDENCE_KIND,
            "digest": digest,
            "body": body,
        }
    )
    rehashed_event_id = content_identity(
        {
            "stream_id": "stream:intent",
            "sequence": _M48_PRIOR_EVENT_WATERMARK,
            "global_sequence": _M48_PRIOR_EVENT_WATERMARK,
            "event_type": "intent.evidence_recorded",
            "body": expected_envelope,
        }
    )
    if (
        digest != _M48_M47_MIGRATION_DIGEST
        or tuple(normalized_evidence[:6])
        != (
            _M48_M47_EVIDENCE_ID,
            "",
            _M42_OPERATOR_TASK_CID,
            _M47_EVIDENCE_KIND,
            _M48_M47_MIGRATION_DIGEST,
            _M47_CONTROL_RECORDED_AT,
        )
        or _identity(body) != digest
        or rehashed_evidence_id != _M48_M47_EVIDENCE_ID
        or tuple(normalized_event[:9])
        != (
            _M48_M47_EVENT_ID,
            "stream:intent",
            _M48_PRIOR_EVENT_WATERMARK,
            _M48_PRIOR_EVENT_WATERMARK,
            "intent.evidence_recorded",
            _M42_OPERATOR_TASK_CID,
            "",
            "session:intent",
            _M47_CONTROL_RECORDED_AT,
        )
        or envelope != expected_envelope
        or rehashed_event_id != _M48_M47_EVENT_ID
        or _event_prefix_digest(connection, _M48_PRIOR_EVENT_WATERMARK)
        != (_M48_PRIOR_EVENT_PREFIX_SHA256, _M48_PRIOR_EVENT_WATERMARK)
    ):
        raise MigrationRequired("M48 preserved M47 event/evidence differs")
    return {
        "m47_event_304_preserved_exactly": True,
        "m47_event_id": _M48_M47_EVENT_ID,
        "m47_evidence_id": _M48_M47_EVIDENCE_ID,
    }


def _check_m48_prestart_admission(
    root: Path,
    config: Mapping[str, Any],
) -> dict[str, Any]:
    """Admit only the exact stopped generation-34/event-304 predecessor."""

    population = build_population(root)
    _assert_committed_clean_source(root, population)
    authority = _m48_source_binding_authority(root, population, config)
    _assert_m48_source_delta(root, population, authority)
    control, coordination = _m48_target_paths(root, config, authority)
    _assert_offline(control)
    receipt_path = control.parent / "m48-source-successor-receipt.json"
    m44_path = control.parent / "m44-source-successor-receipt.json"
    if os.path.lexists(receipt_path):
        raise MigrationRequired("M48 prestart admission is already consumed")
    if os.path.lexists(m44_path):
        raise MigrationRequired("M48 superseded M44 receipt unexpectedly exists")
    status_path = control.parent / "quack-owner/quack-state-server.status.json"
    m47_path = control.parent / "m47-source-successor-receipt.json"
    for path, expected_size, expected_sha, noun, expected_mode in (
        (
            control,
            _M48_PRIOR_CONTROL_SIZE,
            _M48_PRIOR_CONTROL_SHA256,
            "M48 stopped control store",
            0o664,
        ),
        (
            coordination,
            _M48_PRIOR_COORDINATION_SIZE,
            _M48_PRIOR_COORDINATION_SHA256,
            "M48 coordination store",
            0o664,
        ),
        (
            status_path,
            _M48_STOPPED_STATUS_SIZE,
            _M48_STOPPED_STATUS_SHA256,
            "M48 stopped status",
            0o600,
        ),
        (
            m47_path,
            _M48_M47_RECEIPT_SIZE,
            _M48_M47_RECEIPT_SHA256,
            "M48 preserved M47 receipt",
            0o600,
        ),
    ):
        observed_sha, observed_size = _stable_regular_sha256(
            path, root=root, noun=noun, required_link_count=1
        )
        if (
            observed_size != expected_size
            or observed_sha != expected_sha
            or stat.S_IMODE(os.lstat(path).st_mode) != expected_mode
        ):
            raise MigrationRequired(f"{noun} bytes/mode differ")
    m47_receipt = _verify_m48_preserved_m47_receipt(root, control)
    status, _ = _load_nofollow_json(
        status_path, root=root, noun="M48 stopped Quack status"
    )
    identity = status.get("identity")
    stopped = authority["stopped_owner"]
    marker_path = control.with_name(f".{control.name}.state-owner.json")
    stop_path = status_path.with_name("quack-state-server.stop")
    token_handoff_path = status_path.parent / "env___SAWM_QUACK_TOKEN.quack-token"
    if (
        status.get("lifecycle") != "stopped"
        or not isinstance(identity, Mapping)
        or identity.get("status") != "stopped"
        or identity.get("server_id") != stopped["server_id"]
        or identity.get("process_birth_id") != stopped["process_birth_id"]
        or identity.get("database_uuid") != stopped["database_uuid"]
        or identity.get("store_id") != stopped["store_id"]
        or identity.get("listen_uri") != stopped["listen_uri"]
        or identity.get("started_at") != stopped["started_at"]
        or identity.get("stopped_at") not in (None, stopped["stopped_at"])
        or identity.get("extension_fingerprint") != _M48_EXTENSION_FINGERPRINT
        or int(identity.get("generation") or 0) != _M48_PRIOR_GENERATION
        or int(identity.get("schema_revision") or 0) != 1
        or int(identity.get("fence_epoch") or 0) != _M48_PRIOR_GENERATION
        or int(identity.get("credential_generation") or 0)
        != _M48_PRIOR_GENERATION
        or int(identity.get("startup_epoch") or 0) != _M48_PRIOR_STARTUP_EPOCH
        or os.path.lexists(marker_path)
        or os.path.lexists(stop_path)
        or os.path.lexists(token_handoff_path)
        or os.path.lexists(control.with_name(f"{control.name}.wal"))
        or os.path.lexists(coordination.with_name(f"{coordination.name}.wal"))
    ):
        raise MigrationRequired("M48 stopped owner status differs")

    import duckdb

    connection = duckdb.connect(str(control), read_only=True)
    try:
        state_rows = _positional_rows(
            connection.execute(
                "SELECT server_id,store_id,database_uuid,process_birth_id,listen_uri,"
                "extension_fingerprint,schema_revision,generation,started_at,stopped_at,"
                "status,revision,extension_schema,extension_json FROM state_servers "
                "WHERE generation=34"
            ).fetchall(),
            14,
        )
        generation_rows = _positional_rows(
            connection.execute(
                "SELECT generation,schema_revision,fence_epoch,revision,database_uuid,"
                "birth_id,created_at,extension_schema,extension_json FROM "
                "store_generations WHERE generation=34"
            ).fetchall(),
            9,
        )
        credential_rows = _positional_rows(
            connection.execute(
                "SELECT credential_id,secret_handle,generation,purpose,created_at,"
                "rotated_at,revoked_at,revision FROM credentials WHERE generation=34"
            ).fetchall(),
            8,
        )
        epoch_rows = _positional_rows(
            connection.execute(
                "SELECT server_id,epoch,fence_epoch,started_at,ended_at FROM "
                "server_epochs WHERE server_id=?",
                [_M48_PRIOR_SERVER_ID],
            ).fetchall(),
            5,
        )
        counts = {
            table: int(connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0])
            for table in (
                "state_servers",
                "store_generations",
                "credentials",
                "server_epochs",
                "capability_snapshots",
            )
        }
        event_head = int(
            connection.execute(
                "SELECT COALESCE(MAX(global_sequence),0) FROM domain_events"
            ).fetchone()[0]
        )
        event_count = int(
            connection.execute("SELECT COUNT(*) FROM domain_events").fetchone()[0]
        )
        evidence_count = int(
            connection.execute("SELECT COUNT(*) FROM evidence_nodes").fetchone()[0]
        )
        event_type_counts = _m43_event_type_counts_on(
            connection, _M48_PRIOR_EVENT_WATERMARK
        )
        task_rows = _positional_rows(
            connection.execute(
                "SELECT task_alias,status,revision FROM tasks ORDER BY task_alias"
            ).fetchall(),
            3,
        )
        prefix = _event_prefix_digest(connection, _M48_PRIOR_EVENT_WATERMARK)
        semantic = _semantic_authority_digest_on(connection)
        projection = _m43_projection_cid_on(
            connection, _M48_PRIOR_EVENT_WATERMARK
        )
        preserved = _verify_m48_preserved_m47_materialization(
            connection, m47_receipt
        )
        target_event = connection.execute(
            "SELECT 1 FROM domain_events WHERE global_sequence=?",
            [_M48_TARGET_EVENT_WATERMARK],
        ).fetchone()
    finally:
        connection.close()
    observed_heads = {
        str(alias): {"status": str(value), "revision": int(revision)}
        for alias, value, revision in task_rows
    }
    if (
        state_rows
        != [
            (
                _M48_PRIOR_SERVER_ID,
                _M48_STORE_ID,
                _M48_DATABASE_UUID,
                _M48_PRIOR_PROCESS_BIRTH_ID,
                "quack:127.0.0.1:24070",
                _M48_EXTENSION_FINGERPRINT,
                1,
                34,
                _M48_PRIOR_STARTED_AT,
                _M48_PRIOR_STOPPED_AT,
                "stopped",
                2,
                "",
                "{}",
            )
        ]
        or generation_rows
        != [
            (
                34,
                1,
                34,
                0,
                _M48_DATABASE_UUID,
                _M48_PRIOR_PROCESS_BIRTH_ID,
                _M48_PRIOR_STARTED_AT,
                "",
                "{}",
            )
        ]
        or credential_rows
        != [
            (
                f"cred:{_M48_PRIOR_SERVER_ID}:34",
                "env://SAWM_QUACK_TOKEN",
                34,
                "quack-auth",
                _M48_PRIOR_STARTED_AT,
                None,
                None,
                0,
            )
        ]
        or epoch_rows
        != [
            (
                _M48_PRIOR_SERVER_ID,
                _M48_PRIOR_STARTUP_EPOCH,
                34,
                _M48_PRIOR_STARTED_AT,
                _M48_PRIOR_STOPPED_AT,
            )
        ]
        or counts
        != {
            "state_servers": 34,
            "store_generations": 34,
            "credentials": 34,
            "server_epochs": 34,
            "capability_snapshots": 34,
        }
        or event_head != _M48_PRIOR_EVENT_WATERMARK
        or event_count != _M48_PRIOR_EVENT_WATERMARK
        or target_event is not None
        or evidence_count != _M48_PRIOR_EVIDENCE_NODE_COUNT
        or event_type_counts
        != (_M48_PRIOR_EVIDENCE_EVENT_COUNT, _M48_VALIDATION_EVENT_COUNT)
        or prefix
        != (_M48_PRIOR_EVENT_PREFIX_SHA256, _M48_PRIOR_EVENT_WATERMARK)
        or projection != _M48_PRIOR_PROJECTION_CID
        or semantic != _M48_SEMANTIC_AUTHORITY_DIGEST
        or observed_heads != authority["expected_task_heads"]
        or preserved.get("m47_event_304_preserved_exactly") is not True
    ):
        raise MigrationRequired("M48 exact stopped predecessor projection differs")
    return {
        "schema": SCHEMA,
        "valid": True,
        "action": "admitted_stopped_generation_34_restart_to_generation_35",
        "database_path": str(control),
        "coordination_path": str(coordination),
        "prior_event_watermark": _M48_PRIOR_EVENT_WATERMARK,
        "prior_projection_cid": _M48_PRIOR_PROJECTION_CID,
        "prior_generation": _M48_PRIOR_GENERATION,
        "target_generation": _M48_TARGET_GENERATION,
        "m47_receipt_preserved_exactly": True,
        "m47_event_304_preserved_exactly": True,
        "m44_receipt_absent": True,
        "stopped_owner_bytes_verified": True,
        "coordination_store_bytes_preserved_exactly": True,
        "prestart_authorization_consumed": False,
    }


def _m48_expected_event_body(
    body: Mapping[str, Any],
    *,
    evidence_id: str,
    digest: str,
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    target = authority["target_authority"]
    inner = {
        "evidence_id": evidence_id,
        "parent_evidence_id": "",
        "task_cid": target["operator_task_cid"],
        "evidence_kind": target["evidence_kind"],
        "digest": digest,
        "body": dict(body),
        "created_at": _M48_CONTROL_RECORDED_AT,
        "revision": 0,
    }
    return {
        "schema": "ipfs_accelerate_py/agent-supervisor/intent-event@1",
        "event_type": "intent.evidence_recorded",
        "subject_id": evidence_id,
        "body": inner,
        "recorded_at": _M48_CONTROL_RECORDED_AT,
        "owner_id": "sawm-r2-m48-live-source-sealer",
    }


def _inspect_m48_live_projection(
    source: Any,
    population: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    expected_event_watermark: int,
    expected_projection_cid: str,
) -> dict[str, Any]:
    """Verify M48's exact task/goal/plan projection at one watermark."""

    return _inspect_m37_live_projection(
        source,
        population,
        authority,
        expected_event_watermark=expected_event_watermark,
        expected_projection_cid=expected_projection_cid,
    )


def _inspect_m48_generation_restart_rows(
    source: Any,
    identity: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Verify the runtime-generated generation-35 row family exactly."""

    stopped = authority["stopped_owner"]
    server_id = str(identity.get("server_id") or "")
    birth_id = str(identity.get("process_birth_id") or "")
    started_at = str(identity.get("started_at") or "")
    if (
        not server_id
        or not birth_id
        or not started_at
        or server_id == _M48_PRIOR_SERVER_ID
        or birth_id == _M48_PRIOR_PROCESS_BIRTH_ID
        or identity.get("status") != "ready"
        or identity.get("store_id") != _M48_STORE_ID
        or identity.get("database_uuid") != _M48_DATABASE_UUID
        or identity.get("listen_uri") != "quack:127.0.0.1:24070"
        or identity.get("extension_fingerprint") != _M48_EXTENSION_FINGERPRINT
        or int(identity.get("generation") or 0) != _M48_TARGET_GENERATION
    ):
        raise MigrationRequired("M48 live generation-35 identity differs")
    with source.intent._connection(write=False) as connection:
        state_rows = _positional_rows(
            connection.execute(
                "SELECT server_id,store_id,database_uuid,process_birth_id,listen_uri,"
                "extension_fingerprint,schema_revision,generation,started_at,"
                "stopped_at,status,revision,extension_schema,extension_json "
                "FROM state_servers WHERE generation>=34 ORDER BY generation"
            ).fetchall(),
            14,
        )
        generation_rows = _positional_rows(
            connection.execute(
                "SELECT generation,schema_revision,fence_epoch,revision,database_uuid,"
                "birth_id,created_at,extension_schema,extension_json FROM "
                "store_generations WHERE generation>=34 ORDER BY generation"
            ).fetchall(),
            9,
        )
        credential_rows = _positional_rows(
            connection.execute(
                "SELECT credential_id,secret_handle,generation,purpose,created_at,"
                "rotated_at,revoked_at,revision FROM credentials "
                "WHERE generation>=34 ORDER BY generation"
            ).fetchall(),
            8,
        )
        prior_epoch_rows = _positional_rows(
            connection.execute(
                "SELECT server_id,epoch,fence_epoch,started_at,ended_at FROM "
                "server_epochs WHERE server_id=?",
                [_M48_PRIOR_SERVER_ID],
            ).fetchall(),
            5,
        )
        epoch_rows = _positional_rows(
            connection.execute(
                "SELECT server_id,epoch,fence_epoch,started_at,ended_at FROM "
                "server_epochs WHERE server_id=?",
                [server_id],
            ).fetchall(),
            5,
        )
        capability_rows = _positional_rows(
            connection.execute(
                "SELECT snapshot_id,server_id,profile_id,duckdb_version,extension_name,"
                "extension_fingerprint,status,observed_at,body_json FROM "
                "capability_snapshots WHERE server_id=?",
                [server_id],
            ).fetchall(),
            9,
        )
        counts = {
            table: int(connection.execute(f"SELECT COUNT(*) FROM {table}").fetchone()[0])
            for table in (
                "state_servers",
                "store_generations",
                "credentials",
                "server_epochs",
                "capability_snapshots",
            )
        }
    capability_body = json.dumps(
        {
            "status": "compatible",
            "profile_id": "agent-supervisor-duckdb-quack-1.5",
            "extension_fingerprint": _M48_EXTENSION_FINGERPRINT,
        },
        sort_keys=True,
    )
    expected_states = [
        (
            stopped["server_id"],
            stopped["store_id"],
            stopped["database_uuid"],
            stopped["process_birth_id"],
            stopped["listen_uri"],
            _M48_EXTENSION_FINGERPRINT,
            1,
            34,
            stopped["started_at"],
            stopped["stopped_at"],
            "stopped",
            2,
            "",
            "{}",
        ),
        (
            server_id,
            _M48_STORE_ID,
            _M48_DATABASE_UUID,
            birth_id,
            "quack:127.0.0.1:24070",
            _M48_EXTENSION_FINGERPRINT,
            int(identity.get("schema_revision") or 0),
            35,
            started_at,
            None,
            "ready",
            int(identity.get("revision") or 0) + 1,
            "",
            "{}",
        ),
    ]
    expected_generations = [
        (
            34,
            1,
            34,
            0,
            _M48_DATABASE_UUID,
            _M48_PRIOR_PROCESS_BIRTH_ID,
            _M48_PRIOR_STARTED_AT,
            "",
            "{}",
        ),
        (
            35,
            int(identity.get("schema_revision") or 0),
            int(identity.get("fence_epoch") or 0),
            0,
            _M48_DATABASE_UUID,
            birth_id,
            started_at,
            "",
            "{}",
        ),
    ]
    expected_credentials = [
        (
            f"cred:{_M48_PRIOR_SERVER_ID}:34",
            "env://SAWM_QUACK_TOKEN",
            34,
            "quack-auth",
            _M48_PRIOR_STARTED_AT,
            None,
            None,
            0,
        ),
        (
            f"cred:{server_id}:35",
            "env://SAWM_QUACK_TOKEN",
            35,
            "quack-auth",
            started_at,
            None,
            None,
            0,
        ),
    ]
    if (
        state_rows != expected_states
        or generation_rows != expected_generations
        or credential_rows != expected_credentials
        or prior_epoch_rows
        != [
            (
                _M48_PRIOR_SERVER_ID,
                _M48_PRIOR_STARTUP_EPOCH,
                34,
                _M48_PRIOR_STARTED_AT,
                _M48_PRIOR_STOPPED_AT,
            )
        ]
        or epoch_rows
        != [
            (
                server_id,
                int(identity.get("startup_epoch") or 0),
                35,
                started_at,
                None,
            )
        ]
        or capability_rows
        != [
            (
                f"cap:{server_id}:35",
                server_id,
                "agent-supervisor-duckdb-quack-1.5",
                "1.5.5",
                "quack",
                _M48_EXTENSION_FINGERPRINT,
                "compatible",
                started_at,
                capability_body,
            )
        ]
        or counts
        != {
            "state_servers": 35,
            "store_generations": 35,
            "credentials": 35,
            "server_epochs": 35,
            "capability_snapshots": 35,
        }
        or int(identity.get("schema_revision") or 0) != 1
        or int(identity.get("fence_epoch") or 0) != 35
        or int(identity.get("revision") or 0) != 0
        or int(identity.get("credential_generation") or 0) != 35
        or int(identity.get("startup_epoch") or 0) < 1
    ):
        raise MigrationRequired("M48 exact generation-34/35 restart rows differ")
    return {
        "generation_34_35_restart_rows_verified": True,
        "prior_owner_generation": 34,
        "live_owner_generation": 35,
        "live_server_id": server_id,
        "live_process_birth_id": birth_id,
        "live_started_at": started_at,
    }


def _verify_m48_live_materialization(
    source: Any,
    identity: Mapping[str, Any],
    population: Mapping[str, Any],
    config: Mapping[str, Any],
    authority: Mapping[str, Any],
    validation_digest: str,
    *,
    repository_root: Path | None = None,
) -> dict[str, Any]:
    """Verify generation 35 and the sole event-305/evidence append."""

    verification_root = (
        REPO_ROOT if repository_root is None else Path(repository_root).resolve()
    )
    control, _coordination = _m48_target_paths(
        verification_root, config, authority
    )
    m47_receipt = _verify_m48_preserved_m47_receipt(
        verification_root, control
    )
    if os.path.lexists(control.parent / "m44-source-successor-receipt.json"):
        raise MigrationRequired("M48 superseded M44 receipt unexpectedly exists")
    body = _m48_migration_body(population, config, validation_digest)
    digest = _identity(body)
    target = authority["target_authority"]
    from ipfs_accelerate_py.agent_supervisor.task_sources.control_plane_contracts import (
        content_identity,
    )

    evidence_id = content_identity(
        {
            "task_cid": target["operator_task_cid"],
            "evidence_kind": target["evidence_kind"],
            "digest": digest,
            "body": body,
        }
    )
    event_body = _m48_expected_event_body(
        body, evidence_id=evidence_id, digest=digest, authority=authority
    )
    expected_event_id = content_identity(
        {
            "stream_id": "stream:intent",
            "sequence": _M48_TARGET_EVENT_WATERMARK,
            "global_sequence": _M48_TARGET_EVENT_WATERMARK,
            "event_type": "intent.evidence_recorded",
            "body": event_body,
        }
    )
    expected_evidence = (
        evidence_id,
        "",
        target["operator_task_cid"],
        target["evidence_kind"],
        digest,
        _M48_CONTROL_RECORDED_AT,
        _canonical(body).decode("utf-8"),
    )
    expected_event = (
        expected_event_id,
        "stream:intent",
        _M48_TARGET_EVENT_WATERMARK,
        _M48_TARGET_EVENT_WATERMARK,
        "intent.evidence_recorded",
        target["operator_task_cid"],
        "",
        "session:intent",
        _M48_CONTROL_RECORDED_AT,
        _canonical(event_body).decode("utf-8"),
    )
    head = _inspect_m48_live_projection(
        source,
        population,
        authority,
        expected_event_watermark=_M48_TARGET_EVENT_WATERMARK,
        expected_projection_cid=_M48_TARGET_PROJECTION_CID,
    )
    if (
        _m38_projection_cid_at_watermark(source, _M48_PRIOR_EVENT_WATERMARK)
        != _M48_PRIOR_PROJECTION_CID
        or _m38_projection_cid_at_watermark(source, _M48_TARGET_EVENT_WATERMARK)
        != _M48_TARGET_PROJECTION_CID
    ):
        raise MigrationRequired("M48 prior/target projection derivation differs")
    restart = _inspect_m48_generation_restart_rows(source, identity, authority)
    with source.intent._connection(write=False) as connection:
        evidence = connection.execute(
            "SELECT evidence_id,parent_evidence_id,task_cid,evidence_kind,digest,"
            "created_at,body_json FROM evidence_nodes WHERE evidence_id=?",
            [evidence_id],
        ).fetchone()
        event = connection.execute(
            "SELECT event_id,stream_id,sequence,global_sequence,event_type,task_cid,"
            "attempt_id,session_id,recorded_at,body_json FROM domain_events "
            "WHERE global_sequence=?",
            [_M48_TARGET_EVENT_WATERMARK],
        ).fetchone()
        prior_prefix = _event_prefix_digest(
            connection, _M48_PRIOR_EVENT_WATERMARK
        )
        prefix = _event_prefix_digest(connection, _M48_TARGET_EVENT_WATERMARK)
        semantic = _semantic_authority_digest_on(connection)
        preserved = _verify_m48_preserved_m47_materialization(
            connection, m47_receipt
        )
        evidence_count = int(
            connection.execute("SELECT COUNT(*) FROM evidence_nodes").fetchone()[0]
        )
        raw_counts = _m43_event_type_counts_on(
            connection, _M48_TARGET_EVENT_WATERMARK
        )
    if (
        not _m39_exact_row_matches(
            evidence,
            (
                "evidence_id",
                "parent_evidence_id",
                "task_cid",
                "evidence_kind",
                "digest",
                "created_at",
                "body_json",
            ),
            expected_evidence,
        )
        or not _m39_exact_row_matches(
            event,
            (
                "event_id",
                "stream_id",
                "sequence",
                "global_sequence",
                "event_type",
                "task_cid",
                "attempt_id",
                "session_id",
                "recorded_at",
                "body_json",
            ),
            expected_event,
        )
        or evidence_count != _M48_TARGET_EVIDENCE_NODE_COUNT
        or raw_counts
        != (_M48_TARGET_EVIDENCE_EVENT_COUNT, _M48_VALIDATION_EVENT_COUNT)
        or prior_prefix
        != (_M48_PRIOR_EVENT_PREFIX_SHA256, _M48_PRIOR_EVENT_WATERMARK)
        or prefix[1] != _M48_TARGET_EVENT_WATERMARK
        or semantic != _M48_SEMANTIC_AUTHORITY_DIGEST
        or preserved.get("m47_event_304_preserved_exactly") is not True
    ):
        raise MigrationRequired("M48 exact target event/evidence authority differs")
    return {
        **head,
        **restart,
        "migration_digest": digest,
        "migration_evidence_id": evidence_id,
        "migration_evidence_event_id": expected_event_id,
        "target_event_prefix_sha256": prefix[0],
        "prior_event_prefix_verified": True,
        "prior_projection_recomputed": True,
        "target_projection_recomputed": True,
        "m47_receipt_preserved_exactly": True,
        "m47_event_304_preserved_exactly": True,
        "m44_receipt_absent": True,
        "coordination_store_bytes_preserved_exactly": True,
        "semantic_authority_digest": semantic,
        "evidence_node_count": evidence_count,
        "evidence_event_count": int(raw_counts[0]),
        "validation_event_count": int(raw_counts[1]),
        "passed_validation_event_count": _M48_PASSED_VALIDATION_EVENT_COUNT,
        "full_event_and_evidence_body_verified": True,
        "queried_and_mutated_through_live_quack_only": True,
        "direct_authoritative_file_opened": False,
        "plan_revision_changes": 0,
        "goal_revision_changes": 0,
        "evidence_node_changes": 1,
        "evidence_event_changes": 1,
        "validation_event_changes": 0,
        "task_revision_changes": 0,
        "task_status_changes": 0,
        "coordination_semantic_changes": 0,
        "accepted_completion_changes": 0,
        "worker_self_approval": False,
    }


